  str_homestory_chat_14951002 = "คุณเห็นพวกเขาด้วย ราชาแห่ง Cloud Gardens!?",
  str_homestory_chat_14951003 = "อย่าเรียกฉันว่า...",
  str_homestory_chat_14951004 = "เอาล่ะ! หัวหน้า ฉันพนันได้เลยว่าคุณไม่คิดว่าจะได้เห็นกุ้งตัวโตๆ แบบนี้ที่นี่!",
  str_homestory_chat_14951005 = "พวกมันตัวใหญ่มาก! หากคุณขายพวกมันใน Umbraton คุณจะได้เป็นชุด!",
  str_homestory_chat_14951006 = "จริงเหรอ",
  str_homestory_chat_14951007 = "ถูกตัอง! กุ้งเหล่านี้เป็นประเภทที่ดุร้ายมาก ดังนั้นพวกมันจึงสนุกมากที่ได้ดู",
  str_homestory_chat_14951008 = "เมื่อฉันเห็นพวกเขาต่อสู้กัน มันเหมือนกับดูเต่าขนาดใหญ่คู่หนึ่งในฤดูผสมพันธุ์! พวกมันดูเหมือนมีดสองเล่มของฉันเลย!",
  str_homestory_chat_14951009 = "เอ้ย มันทำให้นิ้วของฉันคัน... ฉันอดสงสัยไม่ได้ว่าฉันจะมีโอกาสสู้กับพวกมันไหม...",
  str_homestory_chat_14951010 = "มันคงไม่ใช่ความคิดที่ดี คุณต่างสายพันธุ์...",
  str_homestory_chat_14951011 = "ฉันเดาว่าทั้งหมดที่ฉันทำได้คือมองดูพวกเขา... มีผู้คนจำนวนมากใน Umbraton ที่ไม่สามารถรับเพียงพอกับพวกเขา",
  str_homestory_chat_14951012 = "บางครั้งการต่อสู้ของพวกเขาก็น่าตื่นเต้นจริงๆ!",
  str_homestory_chat_14951013 = "พวกเขายังคงเป็นที่นิยมใน Umbraton?",
  str_homestory_chat_14951014 = "(เราสามารถสร้างโชคได้...)",
  str_homestory_chat_14951015 = "ดูเหมือนว่าคุณค่อนข้างคุ้นเคยกับกุ้งชนิดนี้?",
  str_homestory_chat_14951016 = "เป็นธรรมชาติ! ก่อนอื่นเรียกว่ากุ้งฮ่องเต้",
  str_homestory_chat_14951017 = "ประการที่สอง ฉันพบว่าพวกเขาซุ่มซ่อนอยู่ในหลายแห่งจนถึงตอนนี้",
