  str_homestory_chat_14951020 = "หลายชนิด?",
  str_homestory_chat_14951021 = "จริงๆแล้วมีแค่สองแบบ ที่พบมากที่สุดคือสีน้ำเงิน",
  str_homestory_chat_14951022 = "ใช่แล้ว นั่นคือแบบที่ผมเห็น",
  str_homestory_chat_14951023 = "แน่นอนมันเป็น นอกจากสีน้ำเงินแล้วยังมีสีน้ำตาลอีกด้วย นั่นคือสิ่งที่อาจเรียกได้ว่าเป็นผลิตภัณฑ์คุณภาพสูง",
