  str_homestory_chat_14951025 = "ฉันจะหาพวกเขาได้ที่ไหน",
  str_homestory_chat_14951026 = "ขั้นแรก คุณต้องใช้กุ้งบลูบรอเลอร์หรือที่รู้จักกันอย่างเป็นทางการว่ากุ้งจักรพรรดิโคบอลต์",
