  str_homestory_chat_14951030 = "มั่นใจได้เลยว่าฉันจะทำให้คุณได้ในสิ่งที่สมควรได้รับ!",
  str_homestory_chat_14951031 = "แต่จะจับกุ้งจักรพรรดิโคบอลต์ได้ที่ไหน?",
