  str_homestory_chat_15031024 = "อย่างไรก็ตาม Bighead Carp ขี้ขลาดมาก ฉันต้องใช้เวลาตลอดไปในการค้นหาสถานที่สองสามแห่งที่พวกเขาอาศัยอยู่",
  str_homestory_chat_15031025 = "จับได้ไม่ง่ายเช่นกัน...",
  str_homestory_chat_15031026 = "ถ้าคุณต้องการคนตกปลา ฉันสามารถจัดการได้",
  str_homestory_chat_15031027 = "ร-จริงเหรอบอส?! นั่นจะเป็นภาระอย่างมากจากไหล่ของฉัน ขอขอบคุณ!",
  str_homestory_chat_15031028 = "แต่อย่างที่ฉันพูด Bighead Carp นั้นหายากมาก ฉันลังเลเล็กน้อยที่จะเห็นพวกเขาไป พูดตามตรง...",
  str_homestory_chat_15031029 = "เอาล่ะ เอาล่ะ... จับอะไร?",
  str_homestory_chat_15031030 = "รวดเร็วดั่งจิ้งจอกเช่นเคย! ข้อตกลงก็คือ คุณนำปลาคาร์ปหัวโตตัวเล็กๆ มาให้ฉัน แล้วฉันจะแบ่งปันข้อมูลที่มีค่ากับคุณ",
  str_homestory_chat_15031031 = "ฉันจะบอกคุณอย่างแน่ชัดว่าคุณสามารถตกปลา Bighead Carp ที่ใหญ่กว่าได้ที่ไหน! แต่สิ่งที่เกิดขึ้นหลังจากนั้นขึ้นอยู่กับทักษะการตกปลาของคุณ หัวหน้า",
  str_homestory_chat_15031032 = "แน่นอน ฉันยินดีที่จะเสนอรางวัลอื่นๆ เพื่อนำปลาคาร์ปหัวโตมาให้ฉัน ฉันเป็นคนดีนะ!",
  str_homestory_chat_15031033 = "สำหรับปลาคาร์ปหัวโตที่คุณนำมาให้ฉัน ฉันจะบอกคุณว่าจะหาตัวที่ใหญ่กว่าได้ที่ไหน!",
  str_homestory_chat_15031034 = "ได้ยินมาว่าหนักถึง 50 กิโล! เชื่อไหมว่า!",
  str_homestory_chat_15031035 = "นอกจากนี้ ยังมีโอกาสที่คุณจะจับปลาคาร์ปหัวโตที่หายากและแวววาวเป็นพิเศษ!",
  str_homestory_chat_15031036 = "คุณขายสิ่งนี้ให้ฉันเหมือนคนจาก Umbraton แน่ๆ...",
  str_homestory_chat_15031037 = "แต่ฉันไม่มีแม้แต่ปลาที่เล็กที่สุดที่จะให้คุณตอนนี้",
