  str_homestory_chat_27225009 = "รสชาตินั้นเพียงอย่างเดียวก็เพียงพอแล้วที่จะทำให้คุณรู้สึกอยู่ยงคงกระพัน! เช่นเดียวกับคุณสามารถบรรลุความฝันที่ดุร้ายที่สุดของคุณ!",
  str_homestory_chat_27225010 = "เรา... ยังพูดถึงเรื่องอาหารอยู่หรือเปล่า?",
  str_homestory_chat_27399999 = "ขอให้เป็นวันที่ดี, PlayerName. ฉันอยู่ที่บริการของคุณ ถ้าคุณต้องการอะไร",
  str_homestory_chat_27301001 = "สวัสดี ไมนอส",
  str_homestory_chat_27301002 = "คุณไม่จำเป็นต้องมีมารยาทที่นี่ใน Cloud Gardens ตลอดเวลา ใจเย็นๆ นะ โอเค๊?",
  str_homestory_chat_27301003 = "เป็นไปไม่ได้. ในฐานะพ่อบ้านที่ภาคภูมิใจ ฉันต้องพร้อมที่จะรับใช้เจ้านายของฉันในทุกช่วงเวลา",
  str_homestory_chat_27301004 = "แต่เจ้านายของคุณไม่อยู่ที่นี่ตอนนี้... ใช่ไหม?",
  str_homestory_chat_27301005 = "ไม่ แต่ฉันต้องเตรียมพร้อมในกรณีที่เขาตัดสินใจมาที่นี่",
  str_homestory_chat_27321001 = "อาวุธของคุณ...",
  str_homestory_chat_27321002 = "อา ฉันกำลังมองหาคุณ เพื่อนของฉัน บอกฉันที มีช่างฝีมือระดับปรมาจารย์ใน Cloud Gardens ที่สามารถซ่อมอาวุธได้หรือไม่?",
  str_homestory_chat_27321003 = "ช่าย",
  str_homestory_chat_27321004 = "ฉันควรคุยกับชับบ์คนไหน",
  str_homestory_chat_27321005 = "เอ่อ... ฉันไม่คิดว่าจะมีใครช่วยคุณได้ แต่บางทีเพื่อนของฉันอาจลองได้",
  str_homestory_chat_27321006 = "ไม่อะ",
  str_homestory_chat_27321007 = "เฮ้อ... น่าเสียดาย",
  str_homestory_chat_27321008 = "ปืนของคุณเสียหรือไม่?",
  str_homestory_chat_27321009 = "แน่นอนไม่ ในฐานะบัตเลอร์ที่ภาคภูมิใจ หน้าที่ของฉันคือต้องตรวจสอบให้แน่ใจว่าอุปกรณ์ทั้งหมดของฉันทำงานได้ดี และอาวุธก็ไม่มีข้อยกเว้น",
  str_homestory_chat_27321010 = "ไม่มีการบอกเวลาที่เจ้านายของฉันอาจพบว่าตัวเองอยู่ในสถานการณ์ที่อันตราย",
  str_homestory_chat_27321011 = "นั่นเป็นมืออาชีพของคุณมาก ...",
  str_homestory_chat_27322001 = "ให้ฉันช่วยอะไรไหม?",
  str_homestory_chat_27322002 = "ขอให้เป็นวันที่ดี, PlayerName. คุณช่วยบอกเวลาที่แน่นอนให้ฉันทราบตอนนี้ได้ไหม",
  str_homestory_chat_27322003 = "แน่นอน...? มีอะไรผิดปกติกับนาฬิกาของคุณหรือไม่?",
  str_homestory_chat_27322004 = "แม้แต่เครื่องมือที่แม่นยำที่สุดก็อาจล้มเหลวในบางครั้ง อันที่จริงเมื่อเช้านี้เอง...",
  str_homestory_chat_27322005 = "ฉันสังเกตเห็นว่านาฬิกาของฉันดูเหมือนจะเดินช้ากว่าเมื่อวานเพียงเสี้ยววินาที",
  str_homestory_chat_27322006 = "คุณสังเกตเห็นสิ่งนั้นหรือไม่!",
  str_homestory_chat_27322007 = "ในฐานะพ่อบ้านที่ภาคภูมิใจ เป็นหน้าที่ของฉันที่จะต้องคอยติดตามตลอดเวลา",
  str_homestory_chat_27322008 = "ท้ายที่สุด แม้แต่การเบี่ยงเบนที่น้อยที่สุดจากเวลาที่แน่นอนในส่วนของฉันก็อาจทำลายกำหนดการทั้งหมดของเจ้านายของฉันในวันนั้น",
  str_homestory_chat_27322009 = "อดไม่ได้ที่จะอิจฉานายท่าน...",
  str_homestory_chat_27322010 = "ถ้าเพียงแต่ฉันมีคนแบบเธอที่คอยช่วยเหลือฉันตามกำหนด...",
  str_homestory_chat_27323001 = "มีอะไรอยู่ในความคิดของคุณไมนอส?",
  str_homestory_chat_27323002 = "มีอยู่จริง. บอกฉันที คุณคิดว่าพ่อบ้านรับใช้เจ้านายของเขาได้ดีที่สุดอย่างไร?",
  str_homestory_chat_27323003 = "โดยทำตามคำสั่ง?",
  str_homestory_chat_27323004 = "เชื่อฟังทั้งหมด...",
  str_homestory_chat_27323005 = "ถ้าฉันพูดตรงไปตรงมา... ฉันไม่เห็นด้วยอย่างยิ่ง",
  str_homestory_chat_27323006 = "โดยสนับสนุนพวกเขา?",
  str_homestory_chat_27323007 = "ถูกต้องที่สุด",
  str_homestory_chat_27323008 = "หน้าที่ของพ่อบ้านไม่ได้เป็นเพียงการปฏิบัติตามคำสั่งของเจ้านายเท่านั้น บ่อยครั้งเขาต้องช่วยเจ้านายของเขาให้ตระหนักถึงความผิดพลาดของตัวเอง",
  str_homestory_chat_27323009 = "ในแง่นี้ พ่อบ้านและเจ้านายของเขาสามารถเห็นกันและกันอย่างเท่าเทียมกัน",
  str_homestory_chat_27323010 = "นั่นเป็นความจริงใช่",
  str_homestory_chat_27324001 = "ท่านรู้สึกยังไงกับที่บ้าง",
  str_homestory_chat_27324002 = "มันเป็นสถานที่ที่น่ารัก กว้างใหญ่ แต่สะอาดอย่างไม่น่าเชื่อ",
  str_homestory_chat_27324003 = "ชับบ์ดูเหมือนจะรักษาพื้นที่ได้ค่อนข้างดี",
  str_homestory_chat_27324004 = "ไม่ใช่แค่พวกเขา รู้ไหม? ทุกคนทำหน้าที่ดูแล Cloud Gardens ด้วยเช่นกัน",
  str_homestory_chat_27324005 = "ที่รักของฉัน PlayerNameคุณพูดถูกจริงๆ",
  str_homestory_chat_27324006 = "บอกตามตรง ฉันค่อนข้างอิจฉาที่สถานที่แห่งนี้น่าอยู่มาก",
  str_homestory_chat_27324007 = "สภาพแวดล้อมที่สะอาด อากาศบริสุทธิ์ และแม้แต่ปริมาณแสงแดดที่สถานที่แห่งนี้ได้รับ... ทั้งหมดนั้นโดดเด่นมาก",
  str_homestory_chat_27324008 = "แต่ที่สำคัญที่สุดคือ แทบไม่มีแมลงที่เป็นอันตรายและสัตว์ฟันแทะที่น่ารำคาญอื่นๆ เลย งานของฉันที่นี่มีภาระน้อยลงมาก",
  str_homestory_chat_27324009 = "ฉันดีใจที่คุณชอบที่นี่ ไมนอส!",
