  str_homestory_chat_26921004 = "อีกสามครั้ง?",
  str_homestory_chat_26921005 = "ใช่! อ่านเป็นร้อยรอบก็ไม่เบื่อ!",
  str_homestory_chat_26921006 = "ถ้าดูจากใจของคุณแล้ว ผมว่าคุณอ่านไปสามร้อยรอบแล้วใช่ไหม?",
  str_homestory_chat_26921007 = "ไม่นะ มากกว่า 666 ครั้ง!",
