  str_homestory_chat_26922001 = "คุณยิ้มเหรอ?",
  str_homestory_chat_26922002 = "ฉันแค่นึกถึงบางสิ่งที่ทำให้ฉันมีความสุขมาก เหมือนกับเมื่อคุณนึกถึง Cloud Gardens!",
  str_homestory_chat_26922003 = "มีความสุขอะไรมั้ย?",
  str_homestory_chat_26922004 = "เมื่อไหร่ที่นึกถึงการฟาดฟัน ฉันก็อดยิ้มไม่ได้!",
  str_homestory_chat_26922005 = "ยิ่งเมื่อคิดว่าจะทำลายแผนของคนเลวได้อย่างไรทุกครั้ง!",
  str_homestory_chat_26922006 = "สวนเมฆ?",
  str_homestory_chat_26922007 = "ถูกตัอง! ฉันเฝ้าดูคุณมาระยะหนึ่งแล้ว และสังเกตว่าเมื่อใดก็ตามที่คุณอยู่ใน Cloud Gardens คุณจะมีรอยยิ้มบนใบหน้าเสมอ",
  str_homestory_chat_26922008 = "โดยไม่รู้ตัวและไม่ตั้งใจ",
  str_homestory_chat_26922009 = "แล้ว... คุณยิ้มทำไม?",
  str_homestory_chat_26922010 = "นักเลงยิ้มเมื่อคนร้ายร้องไห้!",
  str_homestory_chat_26922011 = "เมื่อใดก็ตามที่ฉันคิดเกี่ยวกับเรื่องนี้ ฉันอดไม่ได้ที่จะโยนข้อฟรีสไตล์บางข้อ!",
  str_homestory_chat_26922012 = "เจ้าชู้ คนร้ายเห็น! หมัดบินมา และคนร้ายก็เริ่มร้องไห้!",
  str_homestory_chat_26922013 = "ใช่! หึหึหึ!",
  str_homestory_chat_26923001 = "คุณชอบเบสบอลจริงๆเหรอ?",
  str_homestory_chat_26923002 = "ไม่โดยเฉพาะ คุณถามทำไม?",
  str_homestory_chat_26923003 = "ฉันไม่เคยเห็นคุณโดยไม่มีหมวกเบสบอลหรือไม้ตีของคุณ...",
  str_homestory_chat_26923004 = "ฉันแค่ชอบรูปลักษณ์ มันดูไม่เจ๋งสำหรับคุณเหรอ?",
