  str_homestory_chat_26923009 = "โดยพื้นฐานแล้วคุณใช้มันเป็นอาวุธ",
  str_homestory_chat_26923010 = "Super Sadie 666 สวมหมวก Super Sadie 666 เธอตบจริงๆ!",
  str_homestory_chat_26923011 = "โอเค ฉันเข้าใจแล้ว หยุดทำแบบนั้นได้แล้ว...",
