  str_homestory_chat_27522003 = "มันไม่เหมาะกับคุณมากนัก",
  str_homestory_chat_27522004 = "นั่นเป็นเพราะเสื้อผ้าที่รัดแน่นทำให้ฉันรู้สึกอึดอัด บางครั้งฉันยังหายใจลำบาก",
