  str_homestory_chat_28521011 = "คนไม่ตรงต่อเวลาจะทนได้อย่างไร และบางครั้งเราก็ตั้งเวลาไว้ล่วงหน้าแล้ว",
  str_homestory_chat_28521012 = "คนไม่ตรงต่อเวลา...ควรได้รับบทเรียน!",
  str_homestory_chat_28521013 = "นั่นสินะ...",
  str_homestory_chat_28522001 = "คุณกำลังมองหาที่จะซื้ออะไร?",
  str_homestory_chat_28522002 = "ใช่ ฉันต้องการซื้อนาฬิกา",
  str_homestory_chat_28522003 = "แต่เราไม่ขายนาฬิกาใน Cloud Gardens คุณแน่ใจหรือว่ามาถูกที่แล้ว?",
