  str_homestory_chat_28522006 = "ใช่ ส่วนลด Cloud Gardens ในตำนานที่ฉันเคยได้ยินมา",
  str_homestory_chat_28522007 = "น่าจะเป็นส่วนลดมาก บางคนบอกว่ามันถึงหนึ่งในสี่ของราคาปกติ!",
  str_homestory_chat_28522008 = "ไร้สาระ! ใครบอกคุณว่า?",
  str_homestory_chat_28522009 = "ฮะ? แล้วจะไม่ทำ...?",
  str_homestory_chat_28522010 = "ช่างน่าเสียดาย... ฉันไปเจอนาฬิกาใน Umbraton ที่ฉันชอบจริงๆ...",
  str_homestory_chat_28522011 = "แต่มันแพงเกินไป ฉันต้องใช้เวลาสิบปีในการซื้อมัน... ถ้าได้ส่วนลด ฉันจะใช้เวลาแค่สองปีครึ่ง...",
  str_homestory_chat_28522012 = "ว้าว... คุณต้องขอเพิ่ม",
  str_homestory_chat_28522013 = "ทั้งหมดเป็นเพราะ Umbraton แพงเกินไป! ข้าขอสาปแช่งพ่อค้าไร้วิญญาณพวกนั้น!",
  str_homestory_chat_28522014 = "ใช่!",
