  str_homestory_chat_28523004 = "คุณไม่สนใจจริงๆเหรอ?",
  str_homestory_chat_28523005 = "ฉันดื่มสารอาหารที่ Colossus สร้างให้ฉันเป็นเวลาหลายปี...",
  str_homestory_chat_28523006 = "ดังนั้น... คุณไม่รู้วิธีเพลิดเพลินกับอาหารจริงๆ... แต่ฉันเดาว่าฉันก็เหมือนกัน",
  str_homestory_chat_28523007 = "โอ้? จริงหรือ",
  str_homestory_chat_28523008 = "บางครั้งฉันแค่กินบิสกิตหรือเนื้อกระตุกเพื่อให้คำสั่งของฉันไม่ล่าช้า",
