  str_homestory_chat_28523010 = "ดูเหมือนว่าคุณก็ทำงานหนักอยู่เสมอเช่นกัน PlayerName... แต่นั่นอาจเป็นวิธีเดียวที่เราจัดการเพื่อให้บรรลุสิ่งที่เรามี",
