  str_homestory_chat_29922011 = "ฉันรู้จักเต้าหู้! ฉันได้ยินมาว่ามาจากตะวันออกไกล—อาหารมหัศจรรย์ที่เปลี่ยนถั่วให้กลายเป็นของวิเศษ!",
  str_homestory_chat_29922012 = "ละลายในปากและไม่ปรุงรสใดๆ ยังคงมีรสถั่วตามธรรมชาติ...",
