  str_homestory_chat_29221016 = "ฉันได้ยินมาว่าบางคนกินองุ่นแห้งเป็นของว่างในทะเลทรายเรดดีเซล",
  str_homestory_chat_29221017 = "เราไม่ได้พูดถึงเครื่องดื่มอีกต่อไปแล้วใช่ไหม",
  str_homestory_chat_29221018 = "ใช่ แต่ลูกเกดเหล่านั้นสามารถใช้เป็นส่วนผสมในขนมปังหวานได้",
  str_homestory_chat_29221019 = "มันน่าทึ่งจริงๆ",
  str_homestory_chat_29222001 = "เธอชอบอาหารแบบไหนเหรอ?",
  str_homestory_chat_29222002 = "ฉันชอบอาหารร้อน ๆ โดยเฉพาะเนื้อสัตว์ที่ปรุงง่าย ๆ ไม่มีเทคนิคซับซ้อน",
  str_homestory_chat_29222003 = "หมายความว่าไง",
  str_homestory_chat_29222004 = "พูดง่ายๆ ฉันชอบเนื้อต้มคู่กับเครื่องปรุงที่ฉันโปรดปราน",
  str_homestory_chat_29222005 = "ฟังดูสะดวกมาก",
  str_homestory_chat_29222006 = "ใช่—สำหรับทหารแล้ว อาหารชนิดนี้ทั้งสะดวกและอร่อย แถมยังช่วยเติมพลังให้ร่างกายได้อย่างรวดเร็วอีกด้วย",
  str_homestory_chat_29222007 = "ดังนั้น สิ่งสำคัญคือต้องให้ความสนใจกับเสบียงเนื้อสัตว์เสมอ เพื่อให้แน่ใจว่ามีอาหารร้อนพร้อมเสิร์ฟเสมอในสนามรบ",
  str_homestory_chat_29222008 = "ก็อาจเป็นเรื่องที่ซับซ้อนได้...",
  str_homestory_chat_29222009 = "ที่ซับซ้อน?",
  str_homestory_chat_29222010 = "มีหลายสิ่งที่ต้องพิจารณา อันดับแรกคือเชื้อเพลิงที่จะใช้ในการปรุงอาหาร",
  str_homestory_chat_29222011 = "จากนั้นพิจารณาตั้งแต่การรักษาเนื้อสัตว์ไปจนถึงความพึงพอใจในรสชาติของทหารแต่ละคน",
  str_homestory_chat_29222012 = "ทั้งหมดนี้เป็นสิ่งที่ผู้นำต้องพิจารณา และความผิดพลาดเพียงครั้งเดียวในด้านใดด้านหนึ่งอาจทำให้ขวัญกำลังใจตกต่ำได้",
  str_homestory_chat_29222013 = "ว้าว... ฉันไม่รู้ว่าคุณละเอียดแค่ไหน",
  str_homestory_chat_29223001 = "วาดแผนที่?",
  str_homestory_chat_29223002 = "ใช่. คุณเชี่ยวชาญในศิลปะการทำแผนที่หรือไม่?",
  str_homestory_chat_29223003 = "ฉันรู้นิดหน่อย.",
  str_homestory_chat_29223004 = "ยอดเยี่ยม. จากนั้นฉันสามารถใช้ความช่วยเหลือของคุณได้จริงๆ",
  str_homestory_chat_29223005 = "ไม่ขนาดนั้น",
  str_homestory_chat_29223006 = "คุณต้องการแผนที่เพื่ออะไร",
  str_homestory_chat_29223007 = "ฉันอยู่ที่นี่มาหลายวันแล้ว แต่ฉันก็ยังรู้สึกไม่สบายใจบางอย่างในใจ",
  str_homestory_chat_29223008 = "ทำไมคุณถึงรู้สึกแบบนั้น?",
  str_homestory_chat_29223009 = "หลังจากครุ่นคิดอยู่พักใหญ่ ฉันได้แต่สันนิษฐานว่าเป็นเพราะฉันไม่คุ้นเคยกับ Cloud Gardens",
  str_homestory_chat_29223010 = "ให้ฉันพูดแบบนี้—ฉันไม่ค่อยคุ้นเคยกับสถานที่นี้นัก และฉันมักจะรู้สึกไม่ปลอดภัยเมื่ออยู่ในสถานที่ที่ไม่คุ้นเคย",
  str_homestory_chat_29223011 = "คุณไม่ต้องกังวลว่าคนนอกจะมาที่นี่ คุณสามารถผ่อนคลาย",
  str_homestory_chat_29223012 = "แต่อย่างไรก็ตาม... ฉันยังคงรู้สึกราวกับว่าฉันจะต้องเชี่ยวชาญภูมิประเทศด้วยการสำรวจและทำแผนที่เพื่อให้รู้สึกสบายใจ",
  str_homestory_chat_29223013 = "ครับ... เอาไว้คราวหน้านะครับ",
  str_homestory_chat_29224001 = "ต้องการซื้ออาวุธบ้างไหม?",
  str_homestory_chat_29224002 = "โอ้ ดูเหมือนคุณจะเข้าใจฉันผิด ฉันอยากถามคุณว่าคุณจะพิจารณาสร้างพิพิธภัณฑ์ไหม",
  str_homestory_chat_29224003 = "พิพิธภัณฑ์?",
  str_homestory_chat_29224004 = "หนึ่งในการเฉลิมฉลองอาวุธของโลก เช่น ง้าวยาวของ Lumopolis และดาบสั่งการของ Illumina...",
  str_homestory_chat_29224005 = "คุณจำเป็นต้องสร้างพิพิธภัณฑ์เพื่อการนั้นจริงหรือ? ดูเหมือนว่าจะมีอาวุธไม่มากนัก เราแค่กำหนดห้องเก็บของไม่ได้เหรอ?",
  str_homestory_chat_29224006 = "นั่นไม่ใช่เลย! แม้แต่ที่ไหนสักแห่งอย่างอิลลูมินาซึ่งมีอาวุธที่ผลิตขึ้นเป็นจำนวนมากตามธรรมเนียมของตน ก็มีโมเดลและความหลากหลายมากมาย!",
  str_homestory_chat_29224007 = "มีทวน ปืนพก มีดทหารและมีดสั้นมากมาย รวมถึงอาวุธระยะประชิด อาวุธระยะไกล อาวุธเย็น และอาวุธร้อน...",
  str_homestory_chat_29224008 = "ยิ่งกว่านั้น อาวุธที่ใช้โดยขุนนางแห่ง Lumopolis ยังมีรูปแบบที่แตกต่างกันและมีสัญลักษณ์เฉพาะตัวอีกด้วย",
  str_homestory_chat_29224009 = "ฉันสามารถพูดถึงรายละเอียดได้ตลอดไป อย่างไรก็ตาม นั่นเป็นเหตุผลว่าทำไมห้องสะสมเพียงห้องเดียวจึงไม่เพียงพอ",
  str_homestory_chat_29224010 = "มีหลายชนิดจริงๆ...เดี๋ยวก่อน! คุณเป็นเจ้าของอาวุธเหล่านี้ทั้งหมดหรือไม่?",
  str_homestory_chat_29224011 = "แค่ส่วนน้อยแต่นั่นก็ไม่เป็นอุปสรรคต่อการเริ่มสะสมตั้งแต่วินาทีนี้เป็นต้นไป",
  str_homestory_chat_29224012 = "ตอนนี้คุณยังมีไม่มาก... นั่นทำให้ฉันรู้สึกดีขึ้นเล็กน้อย",
  str_homestory_chat_29224013 = "เมื่อพิจารณาว่าที่นี่ปลอดภัยแค่ไหน ฉันควรจะเก็บข้าวของของฉันให้ปลอดภัยที่นี่ นั่นเป็นเหตุผลที่ฉันต้องการสร้างพิพิธภัณฑ์อาวุธโดยเฉพาะ",
  str_homestory_chat_29224014 = "เดี๋ยวฉันต้องคิดดูก่อนนะ",
  str_homestory_chat_30099999 = "วันนี้มีข่าวอะไรไหม?",
  str_homestory_chat_30021001 = "เฮ้ คุณมีงานอดิเรกอะไรไหม?",
  str_homestory_chat_30021002 = "งานอดิเรก...ถามทำไม PlayerName?",
  str_homestory_chat_30021003 = "ฉันแค่อยากรู้คือทั้งหมด",
  str_homestory_chat_30021004 = "บางทีการสังเกตอาจเป็นงานอดิเรกที่แท้จริงเพียงอย่างเดียวของฉัน... แล้วคุณล่ะ?",
