  str_homestory_chat_30021008 = "เดี๋ยวนะ ฉันเป็นคนถามเธอไม่ใช่เหรอ?",
  str_homestory_chat_30021009 = "และนั่นคือคำตอบของฉัน",
  str_homestory_chat_30021010 = "งั้น... งานอดิเรกของคุณคือรวบรวมข่าวกรอง...?",
  str_homestory_chat_30022001 = "ดูเหมือนคุณจะสนุกกับการจดบันทึก",
  str_homestory_chat_30022002 = "ถูกตัอง. ดังสุภาษิตที่ว่า \"ผลงานไม่ดี ย่อมดีกว่าจิตใจที่ปราดเปรื่อง\"",
  str_homestory_chat_30022003 = "ฉันเห็นคุณเขียนและวาดรูปอยู่เสมอ มันดูเหนื่อย",
  str_homestory_chat_30022004 = "ฉันเคยชิน—และฉันมีอาวุธลับ",
  str_homestory_chat_30022005 = "อาวุธลับ?",
  str_homestory_chat_30022006 = "มันเรียกว่าชวเลข.",
  str_homestory_chat_30022007 = "ฟังดูมีพลัง... เหมือนเป็นเคล็ดวิชาลับที่ตกทอดกันไม่ได้",
  str_homestory_chat_30022008 = "คุณต้องจำตัวย่อ ตัวช่วยจำ สัญลักษณ์ และอื่นๆ มากมายใช่ไหม?",
  str_homestory_chat_30022009 = "เอิ่ม ไม่เชิงครับ อันที่จริง วิธีเขียนชวเลขนั้นได้รับการพัฒนาตามนิสัยการเขียนของแต่ละคนเป็นหลัก",
  str_homestory_chat_30022010 = "หา?",
  str_homestory_chat_30022011 = "ในหลายกรณี ตัวย่อที่เกี่ยวข้องจำเป็นต้องเข้าใจด้วยตัวเองเท่านั้น เพราะสุดท้ายคุณก็ยังต้องเขียนตัวย่อที่ถูกต้องอยู่ดี",
  str_homestory_chat_30022012 = "เข้าใจแล้ว",
  str_homestory_chat_30023001 = "ฉันได้ยินว่าคุณต้องการซื้ออะไรไหม",
  str_homestory_chat_30023002 = "ต้องการซื้อกล้องโทรทรรศน์สำหรับสังเกตการณ์",
  str_homestory_chat_30023003 = "คุณชอบสังเกตสัตว์หรือพืชหรือไม่?",
