  str_homestory_chat_30023005 = "เป็นส่วนหนึ่งของมัน?",
  str_homestory_chat_30023006 = "ความเฉลียวฉลาดที่รวบรวมได้จากสัตว์และพืชนั้นถือได้ว่าเป็นตัวช่วยในระดับหนึ่งเท่านั้น...",
  str_homestory_chat_30023007 = "ฉันสังเกตกิจกรรมประจำวันใน Cloud Gardens เป็นหลัก เช่น ชีวิตของ Chubbs...",
  str_homestory_chat_30023008 = "พวกมันอีกแล้ว...",
  str_homestory_chat_30023009 = "อีกแล้วเหรอ",
  str_homestory_chat_30023010 = "ดูเหมือนว่าผู้คนจำนวนมากสนใจพวกเขาในทุกวันนี้",
  str_homestory_chat_30023011 = "เพราะพวกมันมีถิ่นกำเนิดจากที่นี่ไม่เหมือนเรา",
  str_homestory_chat_30023012 = "ยิ่งฉันเรียนรู้มากเท่าไหร่ ฉันก็ยิ่งรู้มากขึ้นเกี่ยวกับ Cloud Gardens ซึ่งจะเป็นประโยชน์กับคุณโดยธรรมชาติ",
  str_homestory_chat_30023013 = "ฉันคิดว่า... ยังดีกว่าที่จะใช้เวลาของคุณพักผ่อนให้มากที่สุดเท่าที่จะทำได้",
  str_homestory_chat_30024001 = "เลี้ยงปลา?",
  str_homestory_chat_30024002 = "ที่นี่รู้สึกว่าเหมาะกับการเลี้ยงปลามาก คุณมีบ่อปลาหรือไม่?",
  str_homestory_chat_30024003 = "เรามีหนึ่งที่นี่",
  str_homestory_chat_30024004 = "ไม่ใช่ตอนนี้...",
  str_homestory_chat_30024005 = "คุณต้องการที่จะเลี้ยงปลาบ้างไหม?",
  str_homestory_chat_30024006 = "ใช่. เมื่อฉันเห็นสระน้ำที่จัตุรัส ฉันก็คิดว่าการเลี้ยงปลาในสวนเมฆาน่าจะดี",
  str_homestory_chat_30024007 = "อย่างไรก็ตาม ปลาที่ฉันชอบนั้นค่อนข้างแปลกและฉันต้องการแยกเลี้ยง",
  str_homestory_chat_30024008 = "คุณกำลังพูดถึงบับเบิ้ล? มันดูอันตรายไปหน่อย",
  str_homestory_chat_30024009 = "อย่ากังวลไปเลย มันเป็นเพียงสิ่งมีชีวิตธรรมดา ความกังวลหลักของฉันคือมันไม่เหมาะสำหรับการเลี้ยงเป็นฝูง ดังนั้นฉันจึงอยากจะเลี้ยงแยกกัน",
  str_homestory_chat_30024010 = "เข้าใจแล้ว... ฉันจะตรวจสอบให้",
  str_homestory_chat_30299999 = "คุณกำลังสำรวจดินแดนของคุณอีกครั้งหรือไม่?",
  str_homestory_chat_30221001 = "แค่ไปเดินเล่น",
  str_homestory_chat_30221002 = "คุณเคยคิดเกี่ยวกับปัญหาด้านความปลอดภัยที่นี่หรือไม่?",
  str_homestory_chat_30221003 = "ได้สิ",
  str_homestory_chat_30221004 = "นั่นคือสิ่งที่เจ้าของควรทำ! ข้อสรุปของคุณคืออะไร?",
  str_homestory_chat_30221005 = "ฉันตรวจสอบแล้ว และดูจากภูมิประเทศของสวนแล้ว มันก็ดีอย่างที่มันเป็น",
  str_homestory_chat_30221006 = "ให้เหมือนเดิม...? ฉันรู้สึกว่าค่อนข้างหละหลวม คุณควรสนับสนุนมาตรการรักษาความปลอดภัย",
  str_homestory_chat_30221007 = "ผมจะรับไว้พิจารณา",
  str_homestory_chat_30221008 = "ไม่อะ",
  str_homestory_chat_30221009 = "นี่มันน่าสมเพชเกินไปแล้ว!",
  str_homestory_chat_30221010 = "นี่เป็นสถานที่ที่หายากมากและทุกคนมาที่นี่เพื่อพักผ่อน",
  str_homestory_chat_30221011 = "ไม่จำเป็นต้องวุ่นวายกับปัญหาด้านความปลอดภัย",
  str_homestory_chat_30221012 = "แน่ใจหรอ",
  str_homestory_chat_30221013 = "ใช่ มันไม่ใช่ปัญหา!",
  str_homestory_chat_30221014 = "แล้วคุณล่ะ เคยคิดบ้างไหม?",
  str_homestory_chat_30221015 = "ฉันทำหลายรอบในช่วงสองสามวันที่ผ่านมา และปลอดภัยตามมาตรฐานปกติ",
  str_homestory_chat_30221016 = "ดีใจที่ได้ยินคุณพูดเช่นนั้น",
  str_homestory_chat_30221017 = "แต่ถึงกระนั้นก็อย่าลดความระมัดระวังเพราะไม่มีใครระวังตัวมากเกินไป ...",
  str_homestory_chat_30221018 = "A-เอาล่ะ",
  str_homestory_chat_30221019 = "ไม่จำเป็นต้องทำเช่นนั้น",
  str_homestory_chat_30221020 = "คุณจะพึงพอใจได้อย่างไร? คุณเคยคิดจริงจังบ้างไหม?",
