  str_homestory_chat_30622004 = "พัฒนาอสังหาริมทรัพย์ มีธรรมชาติมาก แต่สะดวกน้อย",
  str_homestory_chat_30622005 = "ไม่มีศูนย์อาหาร ย่านช้อปปิ้ง ความบันเทิง... คุณไม่สามารถดึงดูดนักท่องเที่ยวได้",
