  str_homestory_chat_30723013 = "น่าจะเป็นสิ่งที่ใครบางคนเรียกว่า \"ความลับในการนัดเดท\"... ไม่ว่าอย่างไร ต้นไม้ที่ไม่ธรรมดาก็ไม่เข้าข่าย",
