  str_homestory_chat_30724009 = "สวนเมฆไม่ใช่สวนสนุก เราไม่ต้องการลูกค้า",
  str_homestory_chat_30724010 = "ทุกคนมาที่นี่เพื่อผ่อนคลาย ครอบครัว Chubbs เพียงแค่ต้องดูแลการดูแลรักษาประจำวัน",
  str_homestory_chat_30724011 = "นั่นเป็นวิธีการทำงานของมันหรือ... อ๋อ",
  str_homestory_chat_30725001 = "ฉันได้ยินว่าคุณกำลังมองหาฉัน?",
  str_homestory_chat_30725002 = "สิ่งที่ฉันต้องการจริงๆ คือการซื้อที่ดินที่นี่",
  str_homestory_chat_30725003 = "อย่าบอกฉันว่ามีใครต้องการสร้างรีสอร์ทและจ้างคุณเป็นผู้จัดการใช่ไหม?",
  str_homestory_chat_30725004 = "ไม่, ผิด, น้อง. ฉันกำลังมองหาที่จะเกษียณที่นี่นะ",
  str_homestory_chat_30725005 = "ยังเป็นเวลาเร็วเกินไปสำหรับสิ่งนั้นใช่ไหม?",
  str_homestory_chat_30725006 = "แค่ความคิดเท่านั้น สภาพแวดล้อมที่นี่ดีเสียอยู่ ไม่วุ่นวาย สงบ...",
  str_homestory_chat_30725007 = "หวังว่าฉันจะทำให้มันถึงวันที่ฉันสามารถเกษียณที่นี่ได้",
