  str_homestory_chat_30801001 = "สวัสดี, บ็อปเปอร์!",
  str_homestory_chat_30801002 = "คุณเห็นฉัน!",
  str_homestory_chat_30801003 = "นั่นเพราะคุณโบกมือให้ฉัน",
  str_homestory_chat_30801004 = "พวกคนใน Rediesel Wrench มักจะไม่สนใจฉัน เสมอ ฉันโดยปกติไม่สามารถรับคำตอบจากพวกเขา",
  str_homestory_chat_30801005 = "ไม่ได้! คุณลองแสดงความคิดเห็นมากขึ้นหรือยัง เช่น ให้คำแนะนำ?",
  str_homestory_chat_30801006 = "นั่นเป็นเหตุผลที่ฉันกลายเป็นนักกลยุทธ์! แต่เหมือนกิ้งก่ายักษ์เท่านั้นที่ให้ความสนใจกับแผนของฉัน...",
  str_homestory_chat_30801007 = "ถ้าซินซาเคยยอมรับคำแนะนำของฉันบ้างเป็นครั้งคราว...",
  str_homestory_chat_30801008 = "ฉันแน่ใจว่าวันนั้นจะมาถึง อย่ายอมแพ้นะ, บ็อปเปอร์!",
  str_homestory_chat_30821001 = "คุณเป็นอย่างไรบ้างในช่วงนี้?",
  str_homestory_chat_30821002 = "ฉันคิดว่าฉันจะกินในอีกสักครู่ ฉันหิวนิดหน่อยน่ะ",
  str_homestory_chat_30821003 = "Cloud Gardens อยู่ห่างจากทะเลทรายเรดีเซลนิดหน่อยนะ และอาจจะไม่มีสิ่งที่ฉันชอบเลยนะครับ",
