  str_homestory_chat_30921009 = "แต่น่าเสียดายที่เธอมาจากลูโมโพลิส และถึงแม้ว่าเธอจะตัดสายสัมพันธ์กับชีวิตอดีตของเธอไปแล้ว...",
  str_homestory_chat_30921010 = "ในสายตาของ \"คนเหล่านั้น\" เธอยังคงอยู่ห่างไกลจากความสมบูรณ์แบบ",
