  str_homestory_chat_30921016 = "แค่พูดความจริงเฉย ๆ",
  str_homestory_chat_30921017 = "ฮิอิโระ",
  str_homestory_chat_30921018 = "ความกล้าหาญของเธอไม่มีใครติเตียนได้ และเธอสั่งการกองทหารของเธอด้วยความเข้มงวดและอำนาจอย่างสูงสุด แต่น่าเสียดาย...",
  str_homestory_chat_30921019 = "ฮิอิโระบางครั้งกล้าหาญไปเกินกว่า \"กล้าหาญ\" จนเธอมักหลงตัวเองในความร้อนแรงของการต่อสู้",
  str_homestory_chat_30921020 = "แน่นอนว่าทหารควรมีความกล้าหาญ แต่ความกล้าหาญไม่ควรมาเสียสละความชนะ",
  str_homestory_chat_30921021 = "ทั้งสองอย่างไม่ได้เสมอกันเสมอไป... ฉันไม่แน่ใจว่าคุณสามารถสังเกตความแตกต่างที่ละเอียดอ่อนได้หรือไม่",
