  str_homestory_chat_30921023 = "ดังนั้น ดูเหมือนว่า... ไม่มีใครเหมาะสมกับบทบาทนี้จริงๆ",
  str_homestory_chat_30921024 = "เอาล่ะ จริงๆ แค่มองจากมุมอื่น: ถ้าหากผู้สมัครคนเหล่านี้มีตัวช่วยที่เหมาะสม เช่น รองผู้บัญชาการ นายทหาร หรืออื่น ๆ มาช่วยเสียง...",
