  str_homestory_chat_30923005 = "ไปตกปลา",
  str_homestory_chat_30923006 = "นั่นเป็นคำพูดที่ซ้ำซากจัง",
  str_homestory_chat_30923007 = "ฉันได้ยินว่าชาวเคเลสไทต์สร้างวิธีการผ่อนคลายที่ไม่ซ้ำใครที่เรียกว่า \"สมาธิ\"",
  str_homestory_chat_30923008 = "ส่วนตัวผม ผมทำสมาธิไม่บ่อยนัก... ทำไมคุณถึงสนใจในการทำสมาธิจู่ๆ ครับ?",
