  str_homestory_chat_30923011 = "เมื่อคุณผ่อนคลาย คุณจะพบเส้นทางที่แท้จริงของคุณและเสริมสร้างทิศทางของความก้าวหน้าของคุณ",
  str_homestory_chat_30923012 = "วิธีการฝึกนี้สำคัญมากสำหรับฉัน—มันช่วยให้ฉันเติมพลัง \"แบตเตอรี่\" ในที่พูดคือการฟื้นฟูตัวเอง",
