  str_homestory_chat_28823012 = "มันเหมือนกับฟองน้ำเล็ก ๆ กำลังเต้นบนลิ้นของคุณ และยังทำให้คุณเรอถ้าดื่มเร็วเกินไปด้วย!",
  str_homestory_chat_28823013 = "นั่นฟังดูเลยเส้นใหญ่ของรสชาติฉันหน่อย...",
  str_homestory_chat_28824001 = "ทำอาหารเช้าเหรอ?",
  str_homestory_chat_28824002 = "ใช่ครับ อาหารเช้าสำคัญมากสำหรับสุขภาพ ตามคำกล่าวที่ว่า \"มื้ออาหารของวันเริ่มต้นด้วยดอว์น\"",
  str_homestory_chat_28824003 = "คำพูดแปลกแฮะ...",
  str_homestory_chat_28824004 = "ฉันก็คิดว่าประเพณีอาหารเช้าของแอสตราบางอย่างแปลกด้วยเช่นกัน",
  str_homestory_chat_28824005 = "ตัวอย่างเช่น ฉันได้ยินว่าเรดีเซล เวรนช์กินสะเต๊ะย่างในมื้อเช้า ในขณะที่บางคนในอัมบราตันดื่มเฉพาะน้ำในตอนเช้าเท่านั้น",
  str_homestory_chat_28824006 = "อืม... ต้องรับว่าเป็นกรณีพิเศษเพียงไม่กี่อย่างเท่านั้นนะ",
  str_homestory_chat_28824007 = "เนื้อเสียบไม้ย่างงั้นเหรอ?",
  str_homestory_chat_28824008 = "นั่นเป็นความชอบส่วนตัวของบางคนในเรดีเซล เวรนช์เท่านั้น...",
  str_homestory_chat_28824009 = "และน้ำ?",
  str_homestory_chat_28824010 = "อืม-อืม, ฉันค่อนข้างแน่ใจว่าพวกเขากำลังพยายามลดน้ำหนักหรือลดค่าใช้จ่ายประจำวันอยู่ค่ะ",
  str_homestory_chat_28824011 = "ไม่ว่าอย่างไรก็ตาม สิ่งเหล่านั้นก็ไม่ใช่ตัวอย่างที่ดีของนิสัยการทานอาหารเช้าใน Astra ปกติ",
  str_homestory_chat_28824012 = "แล้วมื้อเช้าปกติมันเป็นอย่างไรบ้าง?",
