  str_homestory_chat_28824014 = "ฉันเห็น นั่นฟังดูเหมาะสมขึ้น แม้ว่ายังแตกต่างจากอาหารเช้าของเรามากเช่นกัน",
  str_homestory_chat_28799999 = "เป็นอะไรไปล่ะ",
  str_homestory_chat_28701001 = "คุณดูเหมือนว่างเลยตอนนี้นะ",
  str_homestory_chat_28701002 = "อะไรนะ? ฉันจริง ๆ มีเรื่องสำคัญที่ต้องการคุยกับคุณนะ",
  str_homestory_chat_28701003 = "หืม?",
  str_homestory_chat_28701004 = "ใช่คุณเอง! ฉันต้องการทำนายดวงชะตาให้คุณเดี๋ยวนี้เลย!",
  str_homestory_chat_28701005 = "ฟังดูเหมือนคุณเพิ่งคิดขึ้นมาเองนะ...",
  str_homestory_chat_28701006 = "แน่นอนไม่! ฉันคิดเรื่องนี้ขึ้นมาเมื่อนานแล้ว—ฉันหมายความว่า ฉันเป็นห่วงเธอมานานเรื่อยๆ แล้วนะ",
  str_homestory_chat_28701007 = "จากที่ฉันสามารถบอกได้ โชคชะตาของคุณบ่งชี้ว่าคุณมีความอ่อนแอต่อความฟุ้งซ่านอย่างร้ายแรง...",
  str_homestory_chat_28701008 = "ไม่ได้ล้อเล่นใช่ไหม?",
  str_homestory_chat_28701009 = "ใช่! และสำหรับหลายคน สาเหตุของความผิดปกติที่ร้ายแรงนี้คือเวลาว่างเปล่าที่มากเกินไป...",
  str_homestory_chat_28701010 = "ตอนนี้คุณกำลังเรียกฉันว่าขี้เกียจใช่ไหม?!",
  str_homestory_chat_28701011 = "ก็จริงนะ",
  str_homestory_chat_28721001 = "ท่านรู้สึกยังไงกับที่บ้าง",
  str_homestory_chat_28721002 = "ฉันต้องบอกว่า ฮวงจุ้ยที่นี่น่าทึ่งจริง ๆ...",
  str_homestory_chat_28721003 = "การทำนายของฉันบอกว่า ที่นี่เหมาะสมอย่างยิ่งสำหรับใช้ชีวิตในความสงบและความปลอดภัย",
  str_homestory_chat_28721004 = "เหมาะสำหรับเลี้ยงสัตว์หลากหลายชนิดเป็นพิเศษ เช่น นกตัวอย่างเช่น...",
  str_homestory_chat_28721005 = "คุณต้องการเลี้ยงนกที่นี่เหรอ?",
  str_homestory_chat_28721006 = "ถูกต้อง! ขอถามว่ามีนกวิญญาณอื่น ๆ อยู่ที่นี่รึเปล่าครับ/ค่ะ?",
  str_homestory_chat_28721007 = "ได้สิ",
  str_homestory_chat_28721008 = "ไม่นี่",
  str_homestory_chat_28721009 = "อา... น่าเสียดายจัง",
  str_homestory_chat_28721010 = "อย่างไรก็ตาม ฉันต้องถาม... ทำไมคุณถึงต้องการเลี้ยงนกเพิ่มเติมล่ะครับ?",
