  str_homestory_chat_28721012 = "เพื่อนร่วมทาง เอ่อ...? ดูเหมือนว่าพวกเขาไม่ต้องการใครอื่นนอกจากคุณเลยนะ",
  str_homestory_chat_28721013 = "เพื่อปรับตัวให้เข้ากับประเพณีของแอสตราอย่างเหมาะสม พวกเขาต้องการเพื่อนคู่ควรจากแอสตราเช่นกัน",
  str_homestory_chat_28721014 = "และกับเพื่อนใหม่ ๆ พวกเขาอาจจะไม่อยู่ข้างๆฉันตลอดทั้งวันก็ได้นะ",
  str_homestory_chat_28721015 = "ดูเหมือนว่าคุณเพียงแค่ต้องการพักผ่อนจากพวกเขาสักหน่อยเท่านั้นนะ",
  str_homestory_chat_28722001 = "ซื้อขนมหรือครับ/ค่ะ?",
  str_homestory_chat_28722002 = "ใช่เลย! หลังจากที่กินและนอนอย่างดี ฉันรู้สึกสดชื่นและพร้อมที่จะหาของหวานมากินเล็กน้อย",
  str_homestory_chat_28722003 = "ความคิดของฉันได้หลุดไปสู่ตุ๊กตาน้ำตาลที่ทำโดยนักทำนายของเมืองบ้านฉัน ดังนั้นฉันคิดว่าจะถาม Chubbs เกี่ยวกับพวกมัน...",
  str_homestory_chat_28722004 = "พบว่าที่นี่แทบไม่มีของหวานเลย! คนใน Astra ไม่ชอบของหวานขนาดนั้นเหรอ?",
  str_homestory_chat_28722005 = "ไม่ใช่เลย! ลูโมโพลิสและอัมบราตันเป็นที่รู้จักในเรื่องของขนมหวานบางชนิด!",
  str_homestory_chat_28722006 = "ในความเป็นจริง พวกเขามีเค้กหลากหลายชนิดที่มีลายแต่งสวยงาม...",
  str_homestory_chat_28722007 = "มีขนมปังหวานที่มีตัวตุ๊กตาน้ำตาลไหมครับ?",
  str_homestory_chat_28722008 = "มันเค้ก",
  str_homestory_chat_28722009 = "ทั้งคู่เป็นของหวาน สำหรับฉันมันเหมือนกันนะ",
  str_homestory_chat_28722010 = "... ไม่เป็นไร ไม่ว่าอย่างไรก็ตาม มีเค้กที่มีลายดอกไม้สวยๆ อยู่เยอะเลย",
  str_homestory_chat_28722011 = "เรื่องตุ๊กตาน้ำตาล... ฉันไม่คิดว่าเคยเห็นมันมาก่อนเลย",
  str_homestory_chat_28722012 = "งั้นดูเหมือนฉันจะต้องแสดงความสามารถพิเศษของฉันในไม่ช้า คุณจะพาฉันไปดูเค้กเหล่านี้เมื่อไหร่?",
