  str_homestory_chat_28723006 = "มันดูเหมือนแค่ธงธรรมดา ๆ เท่านั้นเอง",
  str_homestory_chat_28723007 = "เฮ้อ... คุณก็เห็นไม่ออกความยิ่งใหญ่ที่อยู่เบื้องหน้าเลยนะ",
  str_homestory_chat_28723008 = "ธงนี้มีพลังอันยิ่งใหญ่: ปัญญาของฟ้าเบื้องบน และความรู้ของแผ่นดินเบื้องล่าง...",
  str_homestory_chat_28723009 = "เมื่อกี๊คุณ...",
  str_homestory_chat_28723010 = "ในทุกกรณี ธงนี้เป็นธงที่มีพลังและพิเศษมากๆ",
