  str_homestory_chat_31421004 = "ใช่ นิดหน่อยครับ...",
  str_homestory_chat_31421005 = "นี่เอง ทำไมไม่ให้ฉันตรวจสอบให้คุณเร็วๆ หน่อยล่ะ?",
  str_homestory_chat_31421006 = "ไม่นะ เปล่าสักหน่อย...",
  str_homestory_chat_31421007 = "ไม่เป็นไรนะ ฉันสัญญา เป็นหมอ ฉันสามารถรู้ได้เมื่อมีคนไม่สบายโดยทั่วไป",
