  str_homestory_chat_31421009 = "เป็นไปได้ว่าคุณอาจกดดันตัวเองมากเกินไปเรื่องนี้ อย่าลืมให้ร่างกายของคุณมีเวลาพักผ่อนเพียงพอนะ",
  str_homestory_chat_31421010 = "คุณต้องการให้ฉันเดินไปส่งห้องคุณไหม?",
