  str_homestory_chat_31422002 = "เดิน... นั่นดีนะ",
  str_homestory_chat_31422003 = "เห็นแก่เส้นทาง คุณมักจะไปเดินเล่นคนเดียวหรือเปล่า?",
  str_homestory_chat_31422004 = "อยากไปด้วยกันมั้ย?",
  str_homestory_chat_31422005 = "นั่นจะเป็นไปได้ไหม? ผมอยากไปเดินเล่นกับคุณมานานแล้วนะ",
  str_homestory_chat_31422006 = "เอาสิ!",
  str_homestory_chat_31422007 = "ใช่ ฉันชอบไปคนเดียว",
  str_homestory_chat_31422008 = "ฉันเห็นด้วยครับ ความเงียบสงบเล็ก ๆ น้อย ๆ สามารถช่วยให้คนจัดระเบียบความคิดของตัวเองได้จริง ๆ",
  str_homestory_chat_31422009 = "เสียใจด้วย... ตอนนี้ฉันมีงานที่ต้องทำเยอะเลย",
  str_homestory_chat_31422010 = "ไม่งั้นก็อยากจะไปเดินเล่นกับคุณนะ",
  str_homestory_chat_31422011 = "เข้าใจแล้ว งั้นอย่าให้ฉันขัดขวางงานของคุณนะ!",
  str_homestory_chat_31422012 = "แล้วเจอกันใหม่นะ",
  str_homestory_chat_31423001 = "พยายามทำงานให้เสร็จครับ",
  str_homestory_chat_31423002 = "คงยากสำหรับคุณบ้างครั้ง แค่จำไว้ว่าอย่าฝืนตัวเองมากเกินไปนะ",
  str_homestory_chat_31423003 = "การทำมากเกินไปบางครั้งอาจจะทำให้ผลลัพธ์ตรงข้ามนะ",
  str_homestory_chat_31423004 = "คุณสามารถเชื่อใจฉันในเรื่องนี้ได้ค่ะ",
  str_homestory_chat_31423005 = "ฉันแน่ใจว่าคุณรู้อยู่แล้ว แต่ฉันรับคนไข้เข้ามาเยอะทุกวันนะครับ",
  str_homestory_chat_31423006 = "ในตอนแรกฉันไม่ได้ให้ความสนใจกับความต้องการของร่างกาย ฉันแค่ต้องการรักษาคนไข้ให้มากที่สุดเท่าที่จะทำได้...",
  str_homestory_chat_31423007 = "ขอบคุณที่สุดท้ายฉันก็ช่วยชีวิตพวกเขาทั้งหมดได้",
  str_homestory_chat_31423008 = "แต่ในที่สุดฉันก็ล้มลงจากความหมดแรงไม่นานหลังจากนั้น...",
