  str_homestory_chat_31424001 = "ฉันวางแผนจัดปาร์ตี้มื้อค่ำอยู่นะ!",
  str_homestory_chat_31424002 = "งานเลี้ยงอาหารค่ำเหรอ?",
  str_homestory_chat_31424003 = "มีปัญหาอะไรรึเปล่า?",
  str_homestory_chat_31424004 = "ไม่ใช่ มันแค่... ทำให้ฉันนึกถึงเรื่องบางอย่างน่ะ",
  str_homestory_chat_31424005 = "ในอดีต เรามักจะมีงานเลี้ยงอาหารเย็นเป็นประจำในครอบครัวของเรา",
  str_homestory_chat_31424006 = "ย้อนกลับมาดู รู้สึกเหมือนเรามีวันแบบนี้เกือบทุกวัน",
  str_homestory_chat_31424007 = "ครอบครัวของคุณต้องใหญ่มากจริงๆ นะ!",
  str_homestory_chat_31424008 = "ฉันเดาว่านั่นจริง อย่างน้อยก็จากมุมมองของตัวเลข...",
