  str_homestory_chat_31921019 = "อะแฮ่ม... ฉันว่าฉันคงจ่ายไม่ไหวนะ",
  str_homestory_chat_31921020 = "เป็นไปไม่ได้เลย! แต่ไม่เป็นไร ฉันจะอยู่ที่นี่เมื่อคุณเปลี่ยนใจ",
  str_homestory_chat_31922001 = "ตอนนี้ฉันแค่กำลังเล่นนิ้วเฉย ๆ นะ",
  str_homestory_chat_31922002 = "คุณหมายถึง คุณเบื่อจนไม่รู้จะทำอะไรดีเพราะไม่มีอะไรทำใช่ไหม?",
  str_homestory_chat_31922003 = "จะว่างั้นก็ไม่ผิด",
  str_homestory_chat_31922004 = "งั้น มาเล่นเกมกับฉันมั้ย",
  str_homestory_chat_31922005 = "เกม? เกมอะไรเหรอ?",
  str_homestory_chat_31922006 = "อย่างง่าย ๆ นึง",
  str_homestory_chat_31922007 = "ฉันมีไนท์เทียมที่นี่ที่ฉันจะโยนขึ้นไปในอากาศครับ",
  str_homestory_chat_31922008 = "แล้วไงต่อ?",
  str_homestory_chat_31922009 = "มาทายกันว่ามันจะลงหัวหรือลงหาง",
  str_homestory_chat_31922010 = "ถ้าคุณถูก แล้วเหรียญนั่นคือของคุณ",
  str_homestory_chat_31922011 = "ถ้าฉันคิดผิดล่ะ?",
  str_homestory_chat_31922012 = "แล้วคุณผิด",
  str_homestory_chat_31922013 = "หา?",
  str_homestory_chat_31922014 = "นั่นหมายความว่า ถ้าคุณเดาผิดก็ไม่เป็นไร ไม่มีเงื่อนไขใดๆ แนบมาด้วย",
  str_homestory_chat_31922015 = "นั่นจะทำให้ฉันได้เปรียบเท่านั้นเหรอ?",
  str_homestory_chat_31922016 = "ใช่ แต่มันเป็นไนท์เทียมเพียงหนึ่งตัวเท่านั้น",
  str_homestory_chat_31922017 = "สิ่งที่เราได้รับจากนี้มีค่ามากกว่าที่เห็น และฉันอาจจะไม่แพ้ จริงไหม?",
  str_homestory_chat_31923001 = "ฉันกำลังทำบัญชีอยู่น่ะ",
  str_homestory_chat_31923002 = "มันมีปัญหาอะไรรึเปล่า? ถ้าจำเป็นฉันสามารถช่วยได้นะ",
  str_homestory_chat_31923003 = "คุณจะอยากลองดูหน่อยไหมครับ?",
  str_homestory_chat_31923004 = "แน่นอนครับ, ความยินดีทั้งหมดเป็นของผม",
  str_homestory_chat_31923005 = "ฉันจะมาช่วยแบกภาระจากมือคุณ...",
  str_homestory_chat_31923006 = "เข้าใจแล้ว บัญชีนี่จัดการและเก็บรักษาได้ไม่ดีเลยนะ",
  str_homestory_chat_31923007 = "ฉันไม่อยากรบกวนพวกเธอเลย",
  str_homestory_chat_31923008 = "ไม่เป็นไร ผมเข้าใจ แต่ถ้าจะตรงไปตรงมา บัญชีเป็นสิ่งที่สำคัญสำหรับทุกสถาบัน",
  str_homestory_chat_31923009 = "ผมมีประสบการณ์เกี่ยวกับการจัดการบัญชีเพียงพอ ดังนั้นผมขอแนะนำบางอย่างได้ไหมครับ?",
  str_homestory_chat_31923010 = "จริงหรือ? คำแนะนำจาก Lady Sheol จะเป็นความช่วยเหลือใหญ่สำหรับฉัน!",
  str_homestory_chat_31923011 = "ขอบคุณครับ!",
  str_homestory_chat_31923012 = "ฮิ ๆ ไม่เป็นไรครับ",
  str_homestory_chat_31923013 = "เป็นแค่ทิปและคำแนะนำเล็ก ๆ",
  str_homestory_chat_31923014 = "ควรจะละเอียดเท่าที่จะทำได้สำหรับแต่ละรายการ แต่ก็ควรกระชับเช่นกัน",
  str_homestory_chat_31923015 = "ไม่ต้องบอกก็รู้ว่าวันที่และวัตถุประสงค์ควรจะถูกแยกเป็นคอลัมน์ที่แตกต่างกัน นอกจากนี้การบันทึกจำนวนเงินในสองรูปแบบสามารถลดโอกาสที่จะผิดพลาดได้",
  str_homestory_chat_31923016 = "แบบนี้จะทำให้การตรวจสอบง่ายขึ้นมาก",
  str_homestory_chat_31923017 = "เข้าใจแล้ว",
  str_homestory_chat_31923018 = "แล้วก็...",
  str_homestory_chat_31923019 = "รอสักครู่! ฉันต้องเขียนสิ่งนี้ลงไป!",
  str_homestory_chat_31924001 = "ฉันหิวน้ำและอยากได้อะไรมาดื่ม",
  str_homestory_chat_31924002 = "กาแฟสักแก้วมั้ยคะ?",
  str_homestory_chat_31924003 = "กาแฟ?",
  str_homestory_chat_31924004 = "ใช่ ฉันเพิ่งซื้อเมล็ดกาแฟที่ดีมาบ้าง",
  str_homestory_chat_31924005 = "จะดีมากถ้าได้ความคิดเห็นคนที่สอง",
  str_homestory_chat_31924006 = "แต่ฉันไม่รู้เรื่องกาแฟเท่าไหร่...",
  str_homestory_chat_31924007 = "ไม่เป็นไร ดื่มเสร็จแล้วก็บอกความคิดเห็นของคุณให้ฉันฟังนะ",
  str_homestory_chat_31924008 = "ฉันไม่ว่าที่จะลองถ้านั่นคือสิ่งที่ต้องทำทั้งหมด",
  str_homestory_chat_31924009 = "คุณชอบกาแฟไหม, คุณเชโอล?",
  str_homestory_chat_31924010 = "ไม่ได้พิเศษ แต่ก็ไม่เกลียดมันนะ",
  str_homestory_chat_31924011 = "แล้วทำไมคุณถึงซื้อเมล็ดกาแฟแทนที่จะเป็นกาแฟคั่วบดล่ะ?",
  str_homestory_chat_31924012 = "ไม่มีเหตุผลเฉพาะเจาะจง ถั่วกาแฟเป็นหนึ่งในธุรกิจของกิลด์ Cloudrover อยู่ดี",
  str_homestory_chat_31924013 = "ฉันเพิ่งรู้สึกอยากจะชิมมันด้วยตัวเองเลย",
  str_homestory_chat_31925001 = "ถึงเวลาฉันต้องศึกษาแล้ว",
  str_homestory_chat_31925002 = "เวลาเรียนหนังสือเหรอ?",
  str_homestory_chat_31925003 = "ในคำอื่น ๆ อ่านหนังสือ",
  str_homestory_chat_31925004 = "เข้าใจแล้ว ขอถามหน่อยว่าคุณวางแผนจะอ่านหนังสือประเภทไหนคะ?",
  str_homestory_chat_31925005 = "ประวัติศาสตร์และภูมิศาสตร์",
  str_homestory_chat_31925006 = "ฉันก็รู้เรื่องเหล่านี้บ้าง ฉันสามารถแนะนำให้คุณได้ไหมครับ?",
  str_homestory_chat_31925007 = "คุณมีความรู้ในด้านนี้หรือเปล่า Lady Sheol?",
  str_homestory_chat_31925008 = "ในฐานะพ่อค้า ยิ่งฉันรู้เยอะ ยิ่งดี ดังนั้นฉันจึงสามารถสนทนากับลูกค้าจากธุรกิจที่แตกต่างกันได้",
  str_homestory_chat_31925009 = "ต้องทำงานหนักจริงๆถึงจะเป็นพ่อค้าที่ยอดเยี่ยมนะ ฉันเห็นแล้ว",
  str_homestory_chat_31925010 = "เศรษฐศาสตร์.",
  str_homestory_chat_31925011 = "โอ้? คุณสนใจเศรษฐศาสตร์เหรอ?",
  str_homestory_chat_31925012 = "ไม่ได้สนใจมากนัก แค่อยากรู้เฉย ๆ",
  str_homestory_chat_31925013 = "ยิ่งไม่ต้องพูดถึงว่าการอ่านหนังสือมากขึ้นก็ยิ่งดีนะ",
  str_homestory_chat_31925014 = "ใช่แล้ว",
  str_homestory_chat_31925015 = "ฉันมีหนังสือที่ดีมากมายจากคอลเลกชันส่วนตัวที่ฉันสามารถแนะนำได้",
  str_homestory_chat_31925016 = "กรุณาแวะมาเมื่อไหร่ก็ได้นะครับ",
  str_homestory_chat_32099999 = "ฉันอยากตกแต่งสำนักงานใหม่! คุณคิดว่าสไตล์ไหนที่ดีที่สุด?",
  str_homestory_chat_32021001 = "สไตล์นอร์ธแลนด์!",
  str_homestory_chat_32021002 = "โอ้? อย่างไรก็ตาม ส่วนใหญ่ของนอร์ธแลนด์ดูเหมือนว่าจะเป็นสิ่งที่มาจากเทพนิยาย โดยเฉพาะการตกแต่งและสถาปัตยกรรมของมัน",
  str_homestory_chat_32021003 = "ฉันไม่รู้เลยว่าคุณเป็นคนโรแมนติกขนาดนี้",
  str_homestory_chat_32021004 = "คุณเป็นนักวิทยาศาสตร์",
  str_homestory_chat_32021005 = "ความคิดที่โรแมนติกแบบนี้น่าจะทำให้คุณรำคาญใช่ไหม?",
  str_homestory_chat_32021006 = "คุณมาจากสหพันธรัฐอิลลูมินา",
  str_homestory_chat_32021007 = "นั่นหมายความว่าคุณไม่เห็นด้วยกับความคิดที่ไม่เป็นไปได้และโรแมนติกแบบนี้ใช่ไหม?",
  str_homestory_chat_32021008 = "ช่างเป็นความเข้าใจผิดอย่างยิ่งใหญ่!",
  str_homestory_chat_32021009 = "เป็นความจริงที่ฉันเป็นนักวิทยาศาสตร์ของสหพันธรัฐอิลลูมินา...",
  str_homestory_chat_32021010 = "ดังนั้น ทุกคนจึงเชื่อว่าฉันไม่ต้องการมีส่วนร่วมใด ๆ กับความโรแมนติกเลย",
  str_homestory_chat_32021011 = "แต่ฉันเชื่อว่านี่เป็นมุมมองที่ใจแคบมากเกี่ยวกับความคิดนั้น",
  str_homestory_chat_32021012 = "เพื่อทำให้สิ่งที่ไม่รู้จักเป็นที่เข้าใจ และเปลี่ยนทุ่งรกร้างเป็นเมือง...",
  str_homestory_chat_32021013 = "นั่นก็ถือว่าโรแมนติกในแบบของมันเองไม่ใช่หรือ?",
  str_homestory_chat_32021014 = "ฉันเดาว่าสมเหตุสมผล",
  str_homestory_chat_32021015 = "ฉันไม่รู้เลยว่าคุณยังเป็นนักโต้เถียงที่มีความชำนาญในการใช้คำด้วย",
  str_homestory_chat_32021016 = "ฉันก็เป็นคนที่รับคำแนะนำได้ดีมากเช่นกันค่ะ",
  str_homestory_chat_32021017 = "นี่เป็นเหตุผลที่ฉันตัดสินใจที่จะตกแต่งห้องทำงานของฉันใหม่ในสไตล์ของนอร์ธแลนด์!",
  str_homestory_chat_32022001 = "สไตล์ลูโมโพลิส!",
  str_homestory_chat_32022002 = "สไตล์ของลูโมโพลิสมีความรู้สึกที่คลาสสิกและเคารพนับถือมาก",
  str_homestory_chat_32022003 = "ด้วยสายไฟและเครื่องจักรทั้งหลายที่วิ่งผ่านสำนักงานของฉัน ฉันไม่แน่ใจว่าลักษณะของการตกแต่งที่เช่นนี้จะเข้ากันได้ดีหรือไม่...",
  str_homestory_chat_32022004 = "แต่บุคลิกภาพของคุณเต็มไปด้วยความขัดแย้ง",
  str_homestory_chat_32022005 = "ความแตกต่างที่เฉียบขาดนั่นเองที่ทำให้มันเหมาะสมอย่างสมบูรณ์แบบ!",
  str_homestory_chat_32022006 = "สิ่งที่ไม่เข้ากันก็มีเสน่ห์ของมันเองเช่นกันนะ",
  str_homestory_chat_32022007 = "ใครบอกว่าสิ่งต่างๆต้องเข้ากันเพื่อที่จะสวยงาม?",
  str_homestory_chat_32022008 = "ฮ่าฮ่าฮ่า! คุณให้ประเด็นที่ดี!",
  str_homestory_chat_32022009 = "ความรู้และความรู้สึกรับรู้ของคุณเป็นคุณภาพที่น่าชื่นชมอย่างยิ่ง",
  str_homestory_chat_32022010 = "เขามาจากการเดินทางข้ามโลกของคุณหรือไม่?",
  str_homestory_chat_32022011 = "ฉันแน่ใจว่าเพราะเรารู้จักกันมานานแล้ว...",
  str_homestory_chat_32022012 = "ฉันจะถือว่านั่นเป็นคำชมนะ!",
  str_homestory_chat_32023001 = "สไตล์อัมบราตัน!",
  str_homestory_chat_32023002 = "เป็นคำแนะนำที่ยากที่จะเสนอนะ",
  str_homestory_chat_32023003 = "เล่าให้ฉันฟังสิ, คุณจะนิยามสไตล์ของอัมบราตันอย่างไรบ้าง?",
  str_homestory_chat_32023004 = "จากประสบการณ์ของฉัน อัมบราตันมักจะเน้นที่ความหลากหลาย",
  str_homestory_chat_32023005 = "นั่นแหละความงามของมัน คุณไม่เห็นหรอ...?",
  str_homestory_chat_32023006 = "มันอาจดูเหมือนเป็นคำแนะนำที่สุ่ม แต่เมื่อคุณคิดจริงๆ...",
  str_homestory_chat_32023007 = "มันคือความคิดที่สมบูรณ์แบบที่รวมคำแนะนำทั้งหมด!",
  str_homestory_chat_32023008 = "ในความเป็นจริง คุณจะไม่ต้องกังวลเรื่องการตกแต่งสำนักงานของคุณอีกต่อไป! ไม่ใช่ในช่วงห้าสิบปีถัดไป!",
  str_homestory_chat_32023009 = "ว้าว... บางครั้งความคิดของฉันดีขนาดที่ฉันยังทึ่งตัวเองเลย!",
  str_homestory_chat_32023010 = "คุณแค่หาข้ออ้างเพราะคุณคิดไม่ออกว่าจะทำอย่างไรดีขึ้นใช่ไหม?",
  str_homestory_chat_32023011 = "ฮิฮิ... ฉันเผลอบอกความจริงไปแล้วสินะ?",
  str_homestory_chat_32023012 = "ไม่เป็นไร ฉันคิดว่าฉันก็มีส่วนผิดที่ทำให้เธอกลายเป็นแบบนี้ ดังนั้นฉันจะไม่ยุ่งเรื่องนี้ต่อแล้ว",
  str_homestory_chat_32023013 = "เธอรู้ทั้งหมดตั้งแต่แรกเลยเหรอ!",
  str_homestory_chat_32023014 = "ฉันเป็นอัจฉริยะในทุกความหมายของคำนั้น อย่าลืมนะ.",
  str_homestory_chat_32024001 = "แบบหลงโจว!",
  str_homestory_chat_32024002 = "ว้าว, ไม่เชื่อได้ว่าคุณจะเสนอแบบนั้น...",
  str_homestory_chat_32024003 = "ฉันมักจะหลงใหลในสไตล์การตกแต่งของแดนที่ห่างไกลนั้น...",
  str_homestory_chat_32024004 = "แต่คุณมีความคิดเบื้องต้นว่าราคาจะเท่าไหร่บ้างไหม?",
  str_homestory_chat_32024005 = "แม้แต่สิ่งง่ายๆ เช่น เก้าอี้ไม้...",
  str_homestory_chat_32024006 = "จะต้องเสียค่าใช้จ่ายเท่ากับการตกแต่งห้องทำงานของฉันทั้งหมดอีกครั้ง!",
  str_homestory_chat_32024007 = "ความหรูหราแบบนั้นจะเสมอเป็นสิ่งที่คนธรรมดาอย่างเราไม่มีวันได้สัมผัส, เพื่อนเคเลสไทต์ของฉัน.",
  str_homestory_chat_32024008 = "\"คนทั่วไป\"?",
  str_homestory_chat_32024009 = "ฉันไม่เคยคิดว่าฉันจะได้ยินเธอเรียกตัวเองว่า \"คนธรรมดา\" ในชีวิตของฉันเลย...",
  str_homestory_chat_32024010 = "หรือว่าคุณต้องการที่จะยกตัวเองขึ้นมาอยู่ในระดับเดียวกับฉันหรือเปล่า...",
  str_homestory_chat_32024011 = "ขอบคุณค่ะ, หลงโจว!",
  str_homestory_chat_32024012 = "มันแพงจริงๆหรือ?",
  str_homestory_chat_32024013 = "ฉันไม่รู้ว่าเฟอร์นิเจอร์หลงโจวจะแพงขนาดนี้...",
  str_homestory_chat_32024014 = "ยกโทษให้ฉัน หลงโจว!",
  str_homestory_chat_32024015 = "... อืม, ขอบคุณที่ได้เตือนฉันว่าฉันจะไม่มีวันสามารถบรรลุความฝันในการมีสำนักงานแบบหลงโจวได้.",
  str_homestory_chat_32024016 = "ตอนนี้ชดเชยความทุกข์ทรมานทางใจของฉันสิ!",
  str_homestory_chat_32024017 = "ต-แต่ฉันไม่มีเงินเลย!",
  str_homestory_chat_32025001 = "สไตล์เคเลสไทต์!",
  str_homestory_chat_32025002 = "สไตล์ของคุณเองหรือ? คำตอบที่ไม่คาดคิดเลยนะ.",
  str_homestory_chat_32025003 = "ฉันหมายถึงลักษณะของคนของฉัน ไม่ใช่ของฉันเอง...",
  str_homestory_chat_32025004 = "แล้วคุณยินดีที่จะมาตกแต่งสำนักงานของฉันด้วยตัวเองหรือไม่?",
  str_homestory_chat_32025005 = "เธอได้ความคิดนั้นจากคำแนะนำของฉันยังไงเนี่ย?!",
  str_homestory_chat_32025006 = "เอ่อ, ในโลกนี้—",
  str_homestory_chat_32025007 = "คนที่คุ้นเคยกับลักษณะของชาวเคเลสไทต์คนเดียวคือคุณเองเท่านั้น",
  str_homestory_chat_32025008 = "ย-คุณไม่จำเป็นต้องพูดแบบนั้นนะ!",
  str_homestory_chat_32025009 = "นอกจากนี้ ยังมีนักประวัติศาสตร์และนักโบราณคดีเยอะมากที่ลูโมโพลิสและสหพันธ์อิลลูมินาที่สามารถช่วยคุณ...",
  str_homestory_chat_32025010 = "ฉันแน่ใจว่าพวกเขารู้ทุกอย่างเกี่ยวกับสไตล์ของชาวเคเลสไทต์",
  str_homestory_chat_32025011 = "ใช่ แต่ทำไมฉันถึงต้องการความช่วยเหลือจากพวกเขา แทนที่จะเป็นคุณ...",
  str_homestory_chat_32025012 = "คุณสามารถให้ฉันเหตุผลได้หรือไม่ แม้แต่เพียงหนึ่งเหตุผล?",
  str_homestory_chat_32025013 = "... ไม่ได้นะ",
  str_homestory_chat_32025014 = "แต่ฉันสามารถนึกออกได้สามเหตุผลดีๆที่ทำให้คุณต้องการความช่วยเหลือจากฉัน",
  str_homestory_chat_32025015 = "หนึ่ง, ฉันราคาถูก สอง, ฉันจะไม่คิดค่าใช้จ่ายเยอะ และสาม, ฉันจะช่วยคุณประหยัดเงิน...",
  str_homestory_chat_32025016 = "ฮ่าๆๆๆ! คุณไม่ควรขายตัวเองถูกเกินไปนะ คุณรู้ไหม?",
  str_homestory_chat_32025017 = "ฉันถามเพราะฉันรู้ว่าคุณจะทำงานตกแต่งสำนักงานของฉันได้ดีมาก",
  str_homestory_chat_32025018 = "และยังเพราะฉันชอบคุยกับคุณมากเลยนะ",
  str_homestory_chat_32025019 = "ก็แค่นั้นแหละ!",
  str_homestory_chat_32199999 = "คุณต้องการอธิษฐานอะไร?",
  str_homestory_chat_32121001 = "สันติภาพโลก",
  str_homestory_chat_32121002 = "ว้าว, สำหรับใครสักคนที่จะสานรับความปรารถนาที่ไม่เห็นแก่ตัวเช่นนี้—",
  str_homestory_chat_32121003 = "คุณก็ไม่ได้จริงจังกับมันเลยสินะ...",
  str_homestory_chat_32121004 = "หรือคุณต้องการสิ่งที่ยิ่งใหญ่จริง ๆ",
  str_homestory_chat_32121005 = "แล้วคุณล่ะ, PlayerName?",
  str_homestory_chat_32121006 = "ไม่ได้จริงจังกับมัน",
  str_homestory_chat_32121007 = "ฮะฮะ, ที่เหมาะกับสไตล์ของคุณนะ",
  str_homestory_chat_32121008 = "คุณไม่เคยเป็นคนที่ปล่อยให้อนาคตขึ้นอยู่กับความหวังและความปรารถนาเท่านั้น คุณจะไล่ตามสิ่งที่คุณต้องการจริง ๆ และทำให้มันเป็นจริง...",
  str_homestory_chat_32121009 = "ฉันต้องการสิ่งที่ยิ่งใหญ่แบบนั้น.",
  str_homestory_chat_32121010 = "ในคำพูดอื่น ๆ ความสงบสุขของโลกคือเป้าหมายที่แท้จริงในชีวิตของคุณ",
  str_homestory_chat_32121011 = "คุณทุ่มเทอย่างยิ่งเพื่อให้แน่ใจว่าทุกก้าวที่คุณเดินจะนำคุณใกล้ชิดกับความฝัน...",
  str_homestory_chat_32121012 = "ในหมื่นปีที่ผ่านมา คนอย่างคุณเสมอทำให้ฉันปวดหัวมากที่สุด",
  str_homestory_chat_32121013 = "หือ? ทำไมล่ะ?",
  str_homestory_chat_32121014 = "เพราะคนเช่นคุณก็คือคนที่สุดท้ายที่จะเปลี่ยนแปลงโลกนี้",
  str_homestory_chat_32122001 = "สันติสุขและความปลอดภัยสำหรับคนที่ฉันรัก",
  str_homestory_chat_32122002 = "ฉันได้ยินคำอธิษฐานแบบนั้นในวัดของฉันเสมอ",
  str_homestory_chat_32122003 = "มันทำให้ฉันสงสัย คนที่ออกมาปรารถนาแบบนี้ พวกเขามีความสุขหรือแค่โชคร้าย?",
  str_homestory_chat_32122004 = "ยินดีแน่นอน!",
  str_homestory_chat_32122005 = "หมายความว่าพวกเขาเก็บเพื่อนและคนที่พวกเขารักไว้ในหัวใจของพวกเขา และต้องการให้พวกเขามีความสุขเช่นกัน...",
  str_homestory_chat_32122006 = "พวกมันจะโชคร้ายได้ยังไงล่ะ?",
  str_homestory_chat_32122007 = "เพราะความสุขมันเป็นสิ่งที่ชั่วคราว",
  str_homestory_chat_32122008 = "...!",
  str_homestory_chat_32122009 = "คุณไม่คิดว่าเหตุผลเดียวที่ทำให้คนปรารถนาแบบนี้ก็เพราะพวกเขารู้ตัวเองว่ามันเป็นอย่างนั้นรึ",
  str_homestory_chat_32122010 = "... ก็มีเหตุผล",
  str_homestory_chat_32122011 = "ในโลกที่ถูกอิคลิพไซท์ครอบครอง เรามักจะต้องเผชิญกับความโชคร้ายที่ไม่คาดคิดเสมอ",
  str_homestory_chat_32122012 = "นั่นเลยที่ฉันต้องการทำทุกอย่างที่ฉันสามารถทำเพื่อให้แน่ใจว่าเพื่อน ๆ ของฉันปลอดภัย",
  str_homestory_chat_32122013 = "แม้ว่ามันจะเป็นเรื่องเล็ก ๆ น้อย ๆ อย่างการอธิษฐานให้เขา",
  str_homestory_chat_32122014 = "เฮ้ จักรวาลนั้นไม่ถาวร แต่คนมักจะหาความแข็งแกร่งและความหมายในชีวิตได้จากความไม่ถาวรนั้น",
  str_homestory_chat_32122015 = "นั่นเองคือเหตุผลที่ฉันมีความนับถือและชื่นชมมนุษย์มากเท่านั้น",
  str_homestory_chat_32123001 = "เพื่อเยี่ยมชมทุกมุมของโลก",
  str_homestory_chat_32123002 = "เอ่อ? นั่นไม่ใช่ความปรารถนาที่ฉันได้ยินทุกวันนะ, PlayerName.",
  str_homestory_chat_32123003 = "คุณมีความสามารถในการทำสิ่งนั้นมากเกินพอแล้ว ดังนั้นทำไมต้องอยากให้มันเป็นความปรารถนาล่ะ?",
  str_homestory_chat_32123004 = "อาจจะมีอะไรบางอย่างกำลังขวางทางอยู่รึเปล่า?",
  str_homestory_chat_32123005 = "ฉันไม่มีเงินเลย",
  str_homestory_chat_32123006 = "\"มีผู้คนบางกลุ่มที่มีชีวิตเพื่อการพักผ่อน แต่สภาพชีวิตปฏิเสธความสุขของพวกเขา\"",
  str_homestory_chat_32123007 = "แต่นั่นเป็นเรื่องง่ายที่จะแก้ไข! เพียงแค่เอาเครื่องประดับของฉันไปจำนำเพื่อแลกเป็นเงินสด!",
  str_homestory_chat_32123008 = "มีสัตว์ประหลาดเยอะเกินไป",
  str_homestory_chat_32123009 = "\"หมีกำลังขวางทางขณะที่เสือและเสือดาวกำลังคำรามที่ด้านข้างของเรา\"",
  str_homestory_chat_32123010 = "แต่แน่นอนว่าแม้แต่ Eclipsites ที่แข็งแกร่งที่สุดก็ไม่เหมือนกับคุณเมื่อมีฉันอยู่ข้างๆ คุณ ใช่ไหม?",
  str_homestory_chat_32123011 = "เห็นอย่างไรล่ะ PlayerName, คุณเข้าใจความหมายของบทกลอนของฉันมั้ย?",
  str_homestory_chat_32123012 = "อื้ม, ฉันได้ยินเรื่องเหล่านั้นมากมายในระหว่างที่เดินทางผ่านหลงโจว",
  str_homestory_chat_32123013 = "ยิ่งฉันเห็นและได้ยินพวกเขามากขึ้น ยิ่งทำให้ฉันเริ่มเข้าใจมากขึ้น",
  str_homestory_chat_32123014 = "คุณจริง ๆ รู้วิธีการเรียนรู้จากการเดินทางของคุณเลยนะ PlayerName!",
  str_homestory_chat_32123015 = "ขอบคุณนะ!",
  str_homestory_chat_32123016 = "ไม่ว่าอย่างไร คุณก็เป็นเพื่อนรักของฉันแล้ว ฉันไม่สามารถปล่อยให้คุณแบกภาระหนักทั้งหมดได้นะ",
  str_homestory_chat_32123017 = "นั่นเป็นเหตุผลที่ฉันจะทำให้ดีที่สุดต่อไปจนกว่าจะถึงวันรับปริญญา!",
  str_homestory_chat_32123018 = "ดี ดี! ฉันจะรอคุณนะ",
  str_homestory_chat_32124001 = "อยู่ซ่อนตัวในโคลอสซัสตลอดไป",
  str_homestory_chat_32124002 = "ฉันเข้าใจเป็นอย่างดี! ไม่มีอะไรสบายได้เท่ากับการห่อตัวเองในรังเล็ก ๆ ของตัวเอง",
  str_homestory_chat_32124003 = "ใช่ไหมล่ะ? บางครั้งการพักผ่อนที่บ้านก็เป็นสิ่งที่เราต้องการอย่างแท้จริงนะ!",
  str_homestory_chat_32124004 = "โดยเฉพาะเมื่ออากาศหนาวและมีหิมะตกข้างนอก, เหมือนในฤดูหนาว...",
  str_homestory_chat_32124005 = "ไม่มีอะไรเทียบเท่ากับการนอนขดตัวที่บ้าน ดื่มเครื่องดื่มอุ่นๆ และอ่านหนังสือที่ดี...",
  str_homestory_chat_32124006 = "คุณทำทั้งหมดนั้นจริงหรือ?",
  str_homestory_chat_32124007 = "ส่วนใหญ่แล้วฉันก็นอนหลับเวลาทั้งหมด",
  str_homestory_chat_32124008 = "คราวหน้าคุณควรลองดูนะ",
  str_homestory_chat_32124009 = "เอาล่ะ มันก็ฟังดูน่าสนใจนะ!",
  str_homestory_chat_32124010 = "ฮืม... ขั้นแรก ฉันต้องหาผ้าห่มใหญ่ๆ ที่ดีก่อน!",
  str_homestory_chat_32124011 = "บางทีคราวหน้าฉันจะทำตามวิธีของคุณล่ะ",
  str_homestory_chat_32124012 = "ก็ได้! เราสามารถทำมันด้วยกันได้เลย!",
  str_homestory_chat_32124013 = "ด้วยวิธีนี้ คุณสามารถปลุกฉันให้ตื่นในเวลาที่เหมาะสมได้นะ!",
  str_homestory_chat_32124014 = "ฉันไม่เคยรู้ว่าความปรารถนาในหัวใจของคุณจะง่ายๆ แบบนี้ PlayerName.",
  str_homestory_chat_32124015 = "ในตอนแรกฉันคิดว่าคุณอยากจะพาคนของคุณกลับมา หรืออะไรที่คล้ายกัน...",
  str_homestory_chat_32124016 = "เปลี่ยนสิ่งที่เช่นนั้นไม่ทันแล้ว...",
  str_homestory_chat_32124017 = "นอกจากนี้ การอธิษฐานควรใช้เพื่อปรับปรุงชีวิตของเราและชีวิตของเพื่อน ๆ ของเรา ใช่ไหมครับ?",
  str_homestory_chat_32124018 = "ถูกต้อง การยอมรับว่าอดีตเป็นเรื่องที่ผ่านมาแล้วนั้นคือการมีความกล้าหาญ",
  str_homestory_chat_32125001 = "เพื่อความสุขของคุณตลอดไป!",
  str_homestory_chat_32125002 = "ฮะ? คุณจะเสียโอกาสครั้งเดียวในชีวิตเพื่อฉันแบบนั้นจริงหรือ?",
  str_homestory_chat_32125003 = "ทำไมละ",
  str_homestory_chat_32125004 = "เพราะความปรารถนาควรจะถูกสร้างขึ้นเพื่อเพื่อน ๆ และครอบครัวของเรา!",
  str_homestory_chat_32125005 = "นอกจากนี้ มันดีกว่าที่จะต่อสู้เพื่อสิ่งที่คุณต้องการ มากกว่าการปรารถนาให้มันเป็นจริง",
  str_homestory_chat_32125006 = "... ฮ่าฮ่าฮ่าฮ่า, ฉันได้ต้องการจะพูดแบบนั้นมานานแล้ว! มันเท่ดีใช่มั้ยละ?",
  str_homestory_chat_32125007 = "...มันทำได้.",
  str_homestory_chat_32125008 = "ไม่จำเป็นต้องหัวเราะเรื่องนี้หรอกนะ ฉันไม่มีทางล้อเลียนเธอเรื่องนี้หรอก",
  str_homestory_chat_32125009 = "ฉันควรขอพรด้วยเหรอ?",
  str_homestory_chat_32125010 = "โอ้? เทพธิดากำลังอธิษฐานหรือ? น่าจะมีครั้งแรกสำหรับทุกอย่างนะ!",
  str_homestory_chat_32125011 = "ด้วยแสงของดวงอาทิตย์และดวงจันทร์ และพลังของแม่น้ำและมหาสมุทร",
  str_homestory_chat_32125012 = "ขอให้เพื่อนของฉัน PlayerName ได้รับความแข็งแรงของร่างกาย การพักผ่อนที่สบายใจ และความสุขในวันที่จะมาถึง",
  str_homestory_chat_32125013 = "ฉ-ฉันได้ยินชื่อตัวเองเมื่อกี้...?",
  str_homestory_chat_32125014 = "ในคำพูดอื่น ๆ ฉันขอให้คุณมีสุขภาพที่ดี อาหารที่ดี การนอนหลับที่ดี...",
  str_homestory_chat_32125015 = "และสุขสันต์วันปีใหม่มากๆนะ!",
  str_homestory_chat_32125016 = "ว้าว...",
  str_homestory_chat_32125017 = "ตอนนี้เราสามารถมีปีที่มีความสุขอีกปีด้วยกันได้แล้ว",
  str_homestory_chat_32125018 = "เชื่อฉันสิ ความปรารถนาของมังกรไม่ควรถูกมองข้ามเลย",
  str_homestory_chat_32125019 = "ค-ครับ! แล้วก็...",
  str_homestory_chat_32125020 = "ขอบคุณเฉินนี่!",
  str_homestory_chat_32299999 = "นายจะทำอะไร PlayerName?",
  str_homestory_chat_32221001a = "อืมม...",
  str_homestory_chat_32221001 = "วันนี้จะอยู่บนเตียงทั้งวันเลย",
  str_homestory_chat_32221002 = "ทั้งวันเลยเหรอ? คุณทำให้ฉันนึกถึงศิษย์สาวของฉันนี่เนาะ.",
  str_homestory_chat_32221003 = "ศิษย์พี่ของคุณเหรอ?",
  str_homestory_chat_32221004 = "ใช่ เขาเคยดูแลฉันดีมาก แต่...",
