  str_homestory_chat_32221008 = "เมื่อฉันคิดถึงมัน เขาคงอยู่ในระดับที่แตกต่างจากเราอย่างสิ้นเชิง",
  str_homestory_chat_32221009 = "จะอ่านหนังสือบ้าง",
  str_homestory_chat_32221010 = "อ่านหนังสือเหรอ? ฉันอยากรู้ว่าคุณชอบอ่านหนังสือประเภทไหนนะ?",
  str_homestory_chat_32221011 = "ในวันวัดของฉันก่อนหน้านี้ ฉันเพียงแค่อ่านหนังสือทุกประเภท",
  str_homestory_chat_32221012 = "นอกจากการศึกษาเรื่องเมตาฟิสิกส์แล้ว เรายังอ่านเกี่ยวกับศิลปะการต่อสู้และทุกอย่างที่เป็นอื่น ๆ",
  str_homestory_chat_32221013 = "ถึงแม้ว่าในสมัยนั้นฉันจะสนใจการฝึกฝนศิลปะการต่อสู้มากกว่าหนังสือ...",
  str_homestory_chat_32221014 = "ว่าแต่ ทำไมเราไม่สอนเพื่อนๆ ฟีนด์ลิ่งเรื่องวรรณกรรมสั้น ๆ ล่ะ?",
