  str_homestory_chat_32222004 = "ดูเหมือนว่าจะมีบางสิ่งที่กำลังทำให้เกิดความวุ่นวายในบ้านเก่า แต่พวกเขาไม่รู้ว่ามันเป็นอิคลิพไซท์หรือสัตว์ป่า",
