  str_homestory_chat_32324003 = "กระต่ายไม่สามารถต่อสู้ได้และอยู่ที่ด้านล่างของโซ่อาหารในธรรมชาติแล้ว",
  str_homestory_chat_32324004 = "ทำไมคุณถึงอยากเป็นสัตว์อ่อนแอแบบนั้นล่ะ?",
