  str_homestory_chat_32325005 = "มีสปีชีส์ของวาฬที่เรียกว่าออร์กา ฉันได้ยินว่าพวกเขาให้ความสำคัญกับครอบครัวมาก",
  str_homestory_chat_32325006 = "พวกเขาจะอยู่กับครอบครัวของตนจนถึงวันสิ้นชีวิต",
  str_homestory_chat_32325007 = "ฉันเดาว่านั่นคือสิ่งที่ฉันเห็นคุณค่าและถูกดึงดูดมาที่นั่น",
  str_homestory_chat_32325008 = "PlayerName...",
  str_homestory_chat_32325009 = "ขอโทษนะ ฉันไม่ได้ตั้งใจจะเตือนคุณถึงอดีตของคุณ",
  str_homestory_chat_32325010 = "ไม่เป็นไร ไม่ต้องห่วงนะ",
  str_homestory_chat_32325011 = "ฉันมีครอบครัวบนโคลอสซัส",
  str_homestory_chat_32325012 = "ดังนั้นความปรารถนาของฉันเป็นจริงแล้ว",
  str_homestory_chat_32325013 = "โซรอซเป็นครอบครัวของฉัน",
  str_homestory_chat_32325014 = "เราจะทำทุกอย่างเพื่อคนอื่น",
  str_homestory_chat_32325015 = "อา ฉันเข้าใจแล้วล่ะ",
  str_homestory_chat_32325016 = "ฉันก็เหมือนคุณเลย",
  str_homestory_chat_32325017 = "ฉันสูญเสียครอบครัวไปนานแล้ว แต่ฉันได้พบครอบครัวใหม่",
  str_homestory_chat_32325018 = "ในทำนองนั้น ครอบครัวมีมากกว่าแค่ความผูกพันทางเลือด",
  str_homestory_chat_32325019 = "ฉันรู้ว่าคุณจะได้รับมัน",
  str_homestory_chat_32325020 = "ขอบคุณค่ะ, เทียเร่",
  str_homestory_chat_32499999 = "ริบบิต!",
  str_homestory_chat_32421001 = "ฉันเห็นว่าเด็กน้อยคนนี้ก็ชอบที่นี่เหมือนกันนะ!",
  str_homestory_chat_32599999 = "ถ้าคุณต้องเลือกงานอดิเรกในการสะสมของ คุณจะเลือกอะไร?",
  str_homestory_chat_32521001 = "ตุ๊กตา.",
  str_homestory_chat_32521002 = "เหมือนกับที่ใช้บนโต๊ะวางกลยุทธ์เพื่อกำหนดแผนการรบหรือเปล่า?",
  str_homestory_chat_32521003 = "ฉันไม่รู้เลยว่าคุณเป็นคนที่หลงไหลในเรื่องทหารขนาดนี้",
  str_homestory_chat_32521004 = "ใช่ถูกต้อง",
  str_homestory_chat_32521005 = "ทุกคนเรียกฉันว่าผู้นำทาง ซึ่งก็ทำให้ฉันเป็นผู้บัญชาการแบบหนึ่ง",
  str_homestory_chat_32521006 = "นอกจากนี้ ไม่มีอะไรผิดหากคุณฝึกฝนกลยุทธ์การต่อสู้เป็นครั้งคราว",
  str_homestory_chat_32521007 = "PlayerName... ฉันไม่รู้เลยว่าคุณเตรียมตระเตรียมสำหรับการต่อสู้ทุกครั้งอย่างละเอียดอ่อน.",
  str_homestory_chat_32521008 = "ฉันกำลังมองคุณในมุมมองใหม่อีกครั้ง",
  str_homestory_chat_32521009 = "ฉันคิดว่าคุณเข้าใจผิด...",
  str_homestory_chat_32521010 = "เมื่อฉันพูดถึงตุ๊กตา ฉันหมายถึงตุ๊กตาที่มีสีสันและมีราคาแพง—",
  str_homestory_chat_32521011 = "เพราะงั้นคุณจะซื้อรุ่นทหารที่ทันสมัยที่สุด พร้อมกับระบบอาวุธครบถ้วนใช่มั้ย?",
  str_homestory_chat_32521012 = "PlayerName... ฉันไม่รู้เลยว่าคุณจะเอาจริงกับการจำลองการต่อสู้ขนาดนี้.",
  str_homestory_chat_32521013 = "ฉันแทบไม่เคยพบคนที่เหมือนฉันเลย",
  str_homestory_chat_32521014 = "เรามาทำให้ดีที่สุดต่อไป โอเค?",
  str_homestory_chat_32521015 = "เอ่อ... โอเค!",
  str_homestory_chat_32522001 = "เฟอร์นิเจอร์.",
  str_homestory_chat_32522002 = "เฟอร์นิเจอร์หรือ? ฉันว่าคุณมีไอเทมเฟอร์นิเจอร์หายากจำนวนมากในสวนลอยฟ้านะ.",
  str_homestory_chat_32522003 = "นั่นคือสิ่งที่คุณชอบเหรอ",
  str_homestory_chat_32522004 = "ใช่เลย! เฟอร์นิเจอร์ไม่ได้ทำให้ชีวิตของเราสบายขึ้นเท่านั้น...",
  str_homestory_chat_32522005 = "มันยังช่วยให้ฉันใกล้ชิดกับเพื่อน ๆ ของฉันมากขึ้นด้วย",
  str_homestory_chat_32522006 = "ใช่ ฉันเคยเห็นคุณและเพื่อน ๆ ของคุณมีการสนทนาอย่างมีความหลงใหลรอบ ๆ เฟอร์นิเจอร์ของคุณ",
  str_homestory_chat_32522007 = "ฉันเข้าใจแล้ว คุณใช้เฟอร์นิเจอร์เป็น \"กับดักเพื่อน\" ในแบบของคุณเอง",
  str_homestory_chat_32522008 = "หลังจากตั้งเฟอร์นิเจอร์ที่ถูกต้องแล้ว คุณก็รอคอยโอกาสที่เหมาะสม—",
  str_homestory_chat_32522009 = "เพื่อสร้างความทรงจำที่ไม่ลืมเลือนจากการผจญภัยของเรา",
  str_homestory_chat_32522010 = "และชิ้นส่วนของเฟอร์นิเจอร์นั้นทำหน้าที่เป็นสิ่งเตือนความทรงจำจากการผจญภัยเหล่านั้นใช่ไหม? ซึ่งมีเหตุผลดีๆ",
  str_homestory_chat_32522011 = "นกเหยี่ยวบางชนิดมีนิสัยคล้ายกัน",
  str_homestory_chat_32522012 = "หลังจากฉีกเหยื่อของพวกมันออกและกินเนื้อ พวกมันจะตกแต่งรังด้วยกระดูก—",
  str_homestory_chat_32522013 = "ว-ว-ว-เดี๋ยวก่อน!",
  str_homestory_chat_32522014 = "มีบางอย่างเกี่ยวกับสิ่งนั้นดูไม่ถูกต้อง!",
  str_homestory_chat_32523001 = "ไวซ์",
  str_homestory_chat_32523002 = "คุณจะรวบรวม... ร้อยโทไวซ์เหรอ? ขอโทษนะ แต่ฉันไม่เข้าใจ",
  str_homestory_chat_32523003 = "สุดท้ายแล้ว เธอก็เป็นคนที่ไม่เหมือนใครเลย",
  str_homestory_chat_32523004 = "คุณหมายความว่าคุณไม่เข้าใจเหรอ? จริงๆแล้วมีไวซ์หลายๆ แบบนะ!",
  str_homestory_chat_32523005 = "เหมือน \"ไวซ์ที่ตะโกนให้ฉันทำความสะอาดคลังสินค้า\" และ \"ไวซ์ที่รบกวนให้ฉันรับงานเพิ่มเติม\"...",
  str_homestory_chat_32523006 = "\"เตือนฉันให้ทำความสะอาดห้อง\" ไวซ์ และ \"บังคับฉันทานอาหารที่ไม่สามารถบรรยายได้ว่าแย่แค่ไหน\" ไวซ์...",
  str_homestory_chat_32523007 = "... ถึงแม้ว่าทุกอย่างดูเป็นลบทั้งหมด ฉันคิดว่าฉันเข้าใจแล้ว.",
  str_homestory_chat_32523008 = "คุณแค่อยากเห็นทุกด้านของร้อยโทไวซ์ใช่มั้ย?",
  str_homestory_chat_32523009 = "อืม, ฉันไม่ได้พูดอย่างนั้นนะ!",
  str_homestory_chat_32524001 = "โคลอสซี่.",
  str_homestory_chat_32524002 = "โคลอสซัส... นี่นายสะสมได้จริงเหรอ?",
  str_homestory_chat_32524003 = "เอาล่ะ แน่นอนว่าฉันไม่ได้วางมันไว้บนชั้นวางหรืออะไรที่คล้ายกันนะ ฉันคิดว่า...",
  str_homestory_chat_32524004 = "สิ่งที่ฉันต้องการจริง ๆ คืออยากเห็นโคลอสซัสเพิ่มขึ้นอีกมากมาย.",
  str_homestory_chat_32524005 = "PlayerName... จากที่ฉันเห็น คุณคงคิดถึงบ้านเกิดมากเลยนะ",
  str_homestory_chat_32524006 = "ท่านพูดถูก",
  str_homestory_chat_32524007 = "ฉันคิดว่าฉันสามารถเกี่ยวข้องได้",
  str_homestory_chat_32524008 = "เมื่อฉันต่อสู้เพื่อกอบกู้เกียรติยศของครอบครัวของฉัน...",
  str_homestory_chat_32524009 = "อะไรก็ตามที่ทำให้ฉันนึกถึงบ้าน จะทำให้จิตใจสู้รบของฉันแข็งแกร่งขึ้นหนึ่งร้อยเท่า",
  str_homestory_chat_32524010 = "มันไม่ได้เชิงนั้นหรอก",
  str_homestory_chat_32524011 = "Colossi มีสิ่งมากมายที่จะสอนฉันเกี่ยวกับตัวเขาเอง รวมถึง Caelestites ด้วย",
  str_homestory_chat_32524012 = "ด้วยความรู้นั้น ฉันสามารถเตรียมตัวรับมือกับปัญหาใด ๆ ที่โซรอซอาจจะมีในอนาคตได้!",
  str_homestory_chat_32524013 = "ดังนั้น แทนที่จะยึดติดกับอดีต คุณต้องสู้เพื่อรักษาสิ่งที่คุณรักในปัจจุบัน...",
  str_homestory_chat_32524014 = "คุณมีความมุ่งมั่นจริงๆ นะ เคเลสไทต์วัน",
  str_homestory_chat_32524015 = "ขอบคุณที่เข้าใจนะ ราเชล",
  str_homestory_chat_32524016 = "ในสายตาของฉัน คุณได้เป็นส่วนหนึ่งของครอบครัวฉันมานานแล้ว",
  str_homestory_chat_32525001 = "ออโรเรียน.",
  str_homestory_chat_32525002 = "นั่นคือความหมายของออโรเรียนสำหรับคุณหรือไม่? สิ่งสะสม?",
  str_homestory_chat_32525003 = "เอาล่ะ ใช่เลย! สุดท้ายแล้วฉันก็เป็นคนที่ชอบทำให้สิ่งต่างๆ สมบูรณ์ในหัวใจ!",
  str_homestory_chat_32525004 = "แล้วมันหมายความว่าอะไรอย่างแน่นอน?",
  str_homestory_chat_32525005 = "อย่าเข้าใจผิดนะ มันเป็นแค่การเปรียบเทียบเฉย ๆ นะ",
  str_homestory_chat_32525006 = "ฉันแค่อยากจะร่วมสู้ด้วยกับออโรเรียนให้มากที่สุดเท่าที่จะทำได้",
  str_homestory_chat_32525007 = "ด้วยวิธีนี้ฉันสามารถพัฒนาคอลเลคชั่นของฉันได้... ฉันหมายถึง ความสามารถในการปรับตัวของฉัน...",
  str_homestory_chat_32525008 = "แล้วก็ไม่มีปัญหาใดที่ยากเกินไปสำหรับฉันที่จะจัดการ! มันเป็นเรื่องที่สมเหตุสมผลใช่ไหม?",
  str_homestory_chat_32525009 = "เข้าใจแล้ว... ขอโทษที่สงสัยคุณเมื่อกี้นะ",
  str_homestory_chat_32525010 = "ฉันชื่นชมเจตนาดีที่น่ายกย่องของคุณ",
  str_homestory_chat_32525011 = "ทำไมเราไม่มีการฝึกฝนการต่อสู้ครั้งหน้าล่ะ?",
  str_homestory_chat_32525012 = "หา?",
  str_homestory_chat_32699999 = "เอาล่ะ ถ้าไม่ใช่เคเลสไทต์คนสุดท้าย! คุณกำลังทำอะไรอยู่หรือ?",
  str_homestory_chat_32621001 = "เอ่อ...",
  str_homestory_chat_32621002 = "ฉันกำลังจะไปออกกำลังกายสักหน่อย",
  str_homestory_chat_32621003 = "เข้าใจแล้ว! ฝึกเพิ่มความแข็งแกร่งนิดหน่อยเหรอ?",
  str_homestory_chat_32621004 = "เหมือนที่ฉันคิดเลย คุณไม่หยุดพักแม้แต่ในวันธรรมดา!",
  str_homestory_chat_32621005 = "เซต้า คุณก็ฝึกฝนบ่อยๆ ด้วยหรือเปล่า?",
  str_homestory_chat_32621006 = "ความรู้และเสน่ห์ของฉันคือคุณสมบัติที่ดีที่สุดของฉัน แม้ไม่ได้ฝึกฝนทางกาย ฉันก็ยังแข็งแกร่งเพียงพอ!",
  str_homestory_chat_32621007 = "ตัวอย่างเช่น คุณเคยเห็นสิงโตฝึกฝนตัวเองมาบ้างหรือไม่?",
  str_homestory_chat_32621008 = "แน่นอนไม่! เพราะเป็นสิ่งที่ยอมรับไม่ได้ที่สัตว์ที่มีพลังแบบธรรมชาติจะฝึกเพื่อที่จะแข็งแกร่งขึ้นอีก!",
  str_homestory_chat_32621009 = "ฉันวางแผนที่จะหยุดพัก",
  str_homestory_chat_32621010 = "ฉันเห็น พักผ่อนก่อนที่จะต้องต่อสู้ในการรบที่โหดร้ายครั้งต่อไปนะครับ?",
  str_homestory_chat_32621011 = "เหมือนที่ฉันคิดเลย คุณพักผ่อนอย่างจริงจังเหมือนกับการทำงานของคุณเลยนะ!",
  str_homestory_chat_32621012 = "คุณก็เหมือนฉันเลย! แม้ว่าทุกคนจะบอกว่าฉันกินของหวานเยอะเกินไป...",
  str_homestory_chat_32621013 = "ฉันมักจะทำให้อาหารที่ทานสมดุลด้วยการทานลูกกวาดที่เติมวิตามินเสมอ!",
  str_homestory_chat_32621014 = "หืม? โอ้โห ใกล้ถึงเวลาที่ฉันต้องไปเจอพวกเขาแล้ว! ขอโทษนะ แต่ฉันต้องไปแล้ว!",
  str_homestory_chat_32621015 = "นั่นก็ดี ฉันจะเจอคุณในภายหลัง",
  str_homestory_chat_32622001 = "ฉันมีงานสำคัญที่ต้องทำในไม่ช้านี้",
  str_homestory_chat_32622002 = "สิ่งสำคัญ? ฟังดูน่าสงสัยมาก...",
  str_homestory_chat_32622003 = "มันเป็นเรื่องสำคัญขนาดไหนที่คุณไม่สามารถบอกเพื่อนของคุณได้หรือ?",
  str_homestory_chat_32622004 = "เพื่อที่จะห่างไกลจากอดีตที่ไม่น่ายินดีของเขา เขาจึงออกไปโดยไม่ได้บอกลา และต้องเผชิญหน้ากับชะตากรรมอันหนักหน่วงคนเดียว...",
  str_homestory_chat_32622005 = "แต่ไม่ต้องห่วงนะ คุณจะไม่เหงาอีกต่อไป! ฉันจะอยู่เคียงข้างคุณทุกที่ที่คุณไป!",
  str_homestory_chat_32622006 = "ขอบคุณเซต้า แต่มันก็แค่งานบำรุงรักษาโคลอสซัสเท่านั้นเอง",
  str_homestory_chat_32622007 = "หา? โอ้, นี่น่าเบื่อจัง",
  str_homestory_chat_32622008 = "อยากช่วยฉันจัดเรียงแฟ้มบ้างไหม?",
  str_homestory_chat_32622009 = "อะไรนะ? คุณหมายถึงว่ามันแค่นั้นเองเหรอ?",
  str_homestory_chat_32622010 = "เอ่อ... ขอโทษนะ แต่ฉันเพิ่งนึกได้ว่าตอนนี้ฉันมีอย่างอื่นที่ต้องทำ",
  str_homestory_chat_32622011 = "นักรบก็อาจจะยุ่งมากได้นะ คุณรู้ไหม! แล้วพบกัน!",
  str_homestory_chat_32623001 = "ไม่ค่อยมีนะ",
  str_homestory_chat_32623002 = "\"ไม่มีอะไรจริง ๆ\" หรือ? ฉันเดาว่านั่นหมายความว่าไม่มีสิ่งเลวร้ายใด ๆ เกิดขึ้น.",
  str_homestory_chat_32623003 = "แต่นักสู้ผู้กู้โลกอย่างเราไม่สามารถประมาทได้!",
  str_homestory_chat_32623004 = "ความชั่วร้ายอาจซ่อนตัวอยู่ทุกมุม ดังนั้นเราต้องระวังมันอยู่เสมอ!",
