  str_homestory_chat_32823002 = "โอ้ ด้วยทั้งหมดของวิเศษที่คุณสามารถเลือกได้ คุณแค่ต้องการไม้กวาดเท่านั้นเหรอ? ความปรารถนาของคุณนั้นค่อนข้างเรียบง่ายเลยนะ.",
