  str_homestory_chat_32823005 = "แต่การสั่งการคนอื่น แม้ว่าฉันจะจ่ายเงินให้พวกเขา ก็ทำให้ฉันรู้สึกไม่สบายใจ...",
  str_homestory_chat_32823006 = "แต่ถ้ามันเป็นไม้กวาดวิเศษ ฉันสามารถสั่งงานได้โดยไม่รู้สึกไม่ดี!",
  str_homestory_chat_32823007 = "แบบนี้นี่เอง คุณนี่ ใจดีจริง ๆ",
  str_homestory_chat_32823008 = "แต่ถ้าคุณยับยั้ง \"ตัวเอง\" เพื่อผู้อื่นมากเกินไป คุณอาจจะหลงทางจากความจริง",
  str_homestory_chat_32823009 = "การดูแลคนอื่นเป็นส่วนหนึ่งของ \"ตัวเอง\"",
  str_homestory_chat_32823010 = "โต้แย้งได้ดี. ความรู้และลึกซึ้งของคุณจริงๆแล้วน่าประทับใจมาก",
  str_homestory_chat_32823011 = "ถ้าคุณสามารถแสดงออกถึงความอ่อนโยนของคุณได้เต็มที่นั้น...",
  str_homestory_chat_32823012 = "คุณจะแน่นอนกลายเป็นนักบุญที่เสียสละตัวเองเหมือนกับเนลส์...",
  str_homestory_chat_32823013 = "ม-มะ ไม่จำเป็นหรอกครับ ผมสบายดีที่เป็นคนธรรมดาเท่านั้น!",
  str_homestory_chat_32823014 = "ดังนั้น ผู้ที่มีความโอหังเพียงเท่านั้นที่จะสามารถเข้าใกล้ \"สัจธรรม\" ได้หรือ?",
