  str_homestory_chat_32823017 = "คำพูดคมของคุณเหมือนกับหนามของกุหลาบ... บางทีมันอาจเป็นความจริงที่แสดงตัวออกมาในตัวคุณ... ใครจะรู้ล่ะ.",
  str_homestory_chat_32823018 = "เจ้าแห่งสัจธรรมคนนี้ไม่ใช่ว่าจะยากที่จะเข้าไปสนิทกับเขาหรือเปล่า...?",
