  str_homestory_chat_32824003 = "ขอโทษที่ถามนะ แต่เป็นเพราะคุณอยากย้อนเวลากลับไป 17 ปีเพื่อเปลี่ยนแปลงสิ่งที่เกิดขึ้นในอีราเวลรึเปล่า?",
