  str_homestory_chat_32824006 = "ถ้าคุณจริง ๆ ได้โอกาสทำให้มันเกิดขึ้น บางที... ฉันจะยืนอยู่ข้างๆคุณ",
  str_homestory_chat_32824007 = "อะไรนะ? ฉันคิดว่าทุกคนคงจะไม่เห็นด้วยกับการเปลี่ยนแปลงที่ใหญ่หลวงในประวัติศาสตร์เช่นนี้...",
  str_homestory_chat_32824008 = "ฉันกลัวที่จะเปลี่ยนแปลงสิ่งต่าง ๆ มากเกินไป",
