  str_homestory_chat_32824011 = "...ผ้าทอแห่งเวลานั้นมีความลึกลับอย่างมาก",
  str_homestory_chat_32824012 = "วิธีการที่ \"อดีต\" ถูกสร้างขึ้นนั้นซับซ้อนกว่าที่เราคิดมากเลย",
  str_homestory_chat_32824013 = "บางครั้ง \"อนาคต\" อาจเป็นสิ่งที่กำหนดรูปร่างของ \"อดีต\"",
  str_homestory_chat_32824014 = "...",
  str_homestory_chat_32825001 = "ยาที่ทำให้คุณสามารถเรียนรู้ขณะที่คุณหลับ",
  str_homestory_chat_32825002 = "...",
  str_homestory_chat_32825003 = "จ-จากดวงตาของคุณ ฉันเห็นความไม่เห็นด้วยอย่างลึกซึ้ง...",
  str_homestory_chat_32825004 = "เฮ้... ฉันชื่นชมความฉลาดของคุณนะ",
  str_homestory_chat_32825005 = "มีนิยายแฟนตาซีที่มุ่งเน้นไปที่มายากลเป็นจำนวนมาก...",
  str_homestory_chat_32825006 = "แต่แม้กระทั่งพวกเขาก็หายากที่จะอธิบายถึงยาที่คุณต้องการ คุณรู้เหตุผลที่เป็นเช่นนี้หรือไม่?",
  str_homestory_chat_32825007 = "นักเขียนไม่กล้าพอหรือ?",
  str_homestory_chat_32825008 = "เพราะความรู้คือเส้นทางเดียวสู่ความจริง",
  str_homestory_chat_32825009 = "และการเรียนรู้เป็นสิ่งหนึ่งที่ไม่ยอมรับทางลัด",
  str_homestory_chat_32825010 = "เข้าใจแล้วหรือยัง",
  str_homestory_chat_32825011 = "...ฉันเข้าใจดีแล้วครับ อาจารย์วิกตอเรีย!",
  str_homestory_chat_32999999 = "คุณเคยสำนึกบาปเรื่องใดๆ ไหม?",
  str_homestory_chat_32921001 = "อยู่ดึกเล่นเกมสามวันติด",
  str_homestory_chat_32921002 = "เกม...? นั่นคืออะไรเหรอ?",
  str_homestory_chat_32921003 = "พวกมันเป็นปีศาจ",
  str_homestory_chat_32921004 = "ปีศาจ? คุณหมายถึงสัตว์ชั่วร้ายเช่นอิคลิพไซท์หรือเนโครเซอร์แวนท์ใช่หรือไม่?",
  str_homestory_chat_32921005 = "ฉันจะปกป้องคุณ PlayerName เพราะนี่แหละคือเหตุผลที่พระเจ้าได้มอบพลังแห่งเลือดศักดิ์สิทธิ์ให้ฉัน",
  str_homestory_chat_32921006 = "เลือดศักดิ์สิทธิ์ไม่สามารถทำอะไรเกี่ยวกับสิ่งนี้ได้",
  str_homestory_chat_32921007 = "ปีศาจที่เรียกว่าเกมใช้ความสุขเป็นเหยื่อ, ทำให้วัยหนุ่มสูญเปล่าและทำให้เงินของฉันหมดไป...",
  str_homestory_chat_32921008 = "แม้แต่นักรบที่แข็งแกร่งที่สุดก็ไม่สามารถหลุดพ้นจากการครอบครองของพวกเขาได้!",
  str_homestory_chat_32921009 = "แต่... แต่ฟังดูเหมือนคุณยอมแพ้ต่อความล่อลวงโดยไม่ต่อสู้เลย",
  str_homestory_chat_32921010 = "คุณต้องปกป้องฉัน",
  str_homestory_chat_32921011 = "ครั้งหน้าที่กรอนรูล่อฉันด้วยเกม คุณต้องขัดขวางเธอ!",
  str_homestory_chat_32921012 = "กรอนรู?",
  str_homestory_chat_32921013 = "เธอคือราชินีปีศาจของเกมในนรก ถ้าไม่ใช่เพราะเธอ ฉันคงไม่มาสิ้นสุดอยู่ที่นี่...",
  str_homestory_chat_32921014 = "นั่นไม่ใช่แค่... การโทษคนอื่นสำหรับความผิดของเธอเหรอ?",
  str_homestory_chat_32921015 = "อาจจะเป็นเพราะนี่คือสิ่งที่คุณควรจะสำนึกผิดจริงๆ คุณไม่คิดเช่นนั้นหรือ?",
  str_homestory_chat_32921016 = "อึก...! เราจะเลิกคุยเรื่องนี้. ลาก่อน!",
  str_homestory_chat_32922001 = "การวางหอคอยผลไม้ในร้านอาหาร",
  str_homestory_chat_32922002 = "หอคอยผลไม้?",
  str_homestory_chat_32922003 = "เอ่อ, คุณรู้จักร้านอาหารที่ถ้าคุณสั่งเมนูหลัก คุณจะได้สลัดผลไม้เองไหมครับ?",
  str_homestory_chat_32922004 = "คุณสามารถเอาเท่าที่คุณต้องการได้ แต่ได้เพียงครั้งเดียวเท่านั้น",
  str_homestory_chat_32922005 = "ดังนั้นการซ้อนสลัดมากที่สุดเท่าที่จะทำได้บนจานเดียวกลายเป็นศิลปะ",
  str_homestory_chat_32922006 = "เอาล่ะ คุณก็เรียง... หอผลไม้ขึ้นมาบนจานของคุณเหรอ?",
  str_homestory_chat_32922007 = "อย่า, อย่ามองฉันแบบนั้น...",
  str_homestory_chat_32922008 = "ต้องใช้ทักษะที่แท้จริง!",
  str_homestory_chat_32922009 = "...ถ้าคุณภูมิใจ ทำไมคุณถึงได้รู้สึกผิด?",
  str_homestory_chat_32922010 = "ฉันทานทั้งหอผลไม้แล้วท้องเสียมาสามวัน...",
  str_homestory_chat_32922011 = "แล้วคุณก็ได้รับการลงโทษจากพระเจ้า; บาปของคุณได้ถูกล้างสะอาดแล้ว, PlayerName.",
  str_homestory_chat_32922012 = "ดวงตาของคุณกลับมาอุ่นอีกครั้ง ทำให้ฉันรู้สึกแปลกๆ มากขึ้น...",
  str_homestory_chat_32923001 = "การเร่งความเร็ว.",
  str_homestory_chat_32923002 = "เร่งความเร็ว...ฉันไม่รู้ว่าโคลอสซัสมีขีดจำกัดความเร็ว",
  str_homestory_chat_32923003 = "ท้องฟ้าตอนนี้เป็นของฉันที่จะเ roam อย่างอิสระ...",
  str_homestory_chat_32923004 = "แต่ในวันที่มีโคลอสซัสจำนวนมากอยู่ในท้องฟ้า มีการกำหนดความเร็วสูงสุดตามประเพณี",
  str_homestory_chat_32923005 = "พวกเขามีหน้าที่รักษาความปลอดภัยของโคลอสซัสและนกตัวอื่น ๆ และฉันตามพวกเขาไปมากส่วนใหญ่",
  str_homestory_chat_32923006 = "เลยทำไมคุณถึงขับรถเร็วล่ะ?",
  str_homestory_chat_32923007 = "วันเกิดของ Vice",
  str_homestory_chat_32923008 = "ฉันเร่งไปที่ Umbraton เพื่อจับหนึ่งในห้าสิบเค้กผลไม้รุ่นพิเศษแบบโอท็อปที่มีจำนวนจำกัด",
  str_homestory_chat_32923009 = "วันเกิดของคาร์ลีน",
  str_homestory_chat_32923010 = "ฉันรีบไปที่ลูโมโพลิสเพื่องานเลี้ยงวันเกิด และต้องรับชุดราตรีของฉันที่ร้านซักแห้งในทาง...",
  str_homestory_chat_32923011 = "อ้อเหรอ...",
  str_homestory_chat_32923012 = "เนื่องจากมันเป็นเพื่อเธอ ฉันไม่สามารถตำหนิคุณได้",
  str_homestory_chat_32923013 = "และคุณได้สารภาพบาปอย่างจริงใจไปแล้วใช่ไหม?",
  str_homestory_chat_32923014 = "ด-ได้ครับ!",
  str_homestory_chat_32923015 = "แม้ไม่มีใครบังคับ คุณก็ยังยึดติดกับธรรมเนียมของตระกูลของคุณและรู้สึกผิดคาดเมื่อคุณทำผิดพวกมัน",
  str_homestory_chat_32923016 = "ตัวตนที่มีอุดมการณ์สูงส่งของคุณน่าชื่นชมจริงๆ",
  str_homestory_chat_32923017 = "พระเจ้าแห่งความจริงจะมอบพรให้คุณ, PlayerName.",
  str_homestory_chat_32923018 = "ขอขอบคุณ... ฉันหมายถึง ขอขอบคุณพระเจ้า!",
  str_homestory_chat_32924001 = "ขาดความเพียร.",
  str_homestory_chat_32924002 = "มันยากสำหรับคุณที่จะยึดติดกับสิ่งต่าง ๆ หรือไม่?",
  str_homestory_chat_32924003 = "ใช่... โดยเฉพาะเมื่อฉันตัดสินใจที่จะออกกำลังกาย อืม...",
  str_homestory_chat_32924004 = "การฝึกฝนร่างกายเป็นกระบวนการที่เจ็บปวด ฉันเคยผ่านมันมาแล้ว ดังนั้นฉันเข้าใจเลย",
  str_homestory_chat_32924005 = "จริงๆ แล้ว คุณไม่จำเป็นต้องผลักดันตัวเอง เพราะแรงของคุณไม่ได้อยู่ในร่างกาย",
  str_homestory_chat_32924006 = "การออกกำลังกายอาจไม่เหมาะกับคุณ แต่ต้องมีสิ่งที่คุณสามารถทำได้ต่อเนื่องอยู่ใช่ไหม?",
  str_homestory_chat_32924007 = "คง... นิดหน่อยมั้ง...",
  str_homestory_chat_32924008 = "เช่นอะไร?",
  str_homestory_chat_32924009 = "กินข้าว... หลับ...",
  str_homestory_chat_32924010 = "...",
  str_homestory_chat_32924011 = "ยังมีอีกนะ! เหมือนว่า...",
  str_homestory_chat_32924012 = "...เหมือนกับการหายใจ!",
  str_homestory_chat_32924013 = "...",
  str_homestory_chat_33099999 = "คุณชอบอ่านหนังสือประเภทไหน?",
  str_homestory_chat_33021001 = "นวนิยาย",
  str_homestory_chat_33021002 = "น่าสนใจ",
  str_homestory_chat_33021003 = "คุณรู้ไหม? สิ่งที่คุณเรียกว่านวนิยายมีประวัติศาสตร์ที่สั้นอย่างน่าประหลาด",
  str_homestory_chat_33021004 = "พวกเขากำลังเริ่มต้นในยุคของฉัน",
  str_homestory_chat_33021005 = "นั่นเป็นข่าวสำหรับฉัน!",
  str_homestory_chat_33021006 = "ฉันคิดว่านิยาย... เอ่อ, มันอยู่ที่นั่นมาตลอดเลยใช่ไหม?",
  str_homestory_chat_33021007 = "เป็นความผิดพลาดทางการรับรู้ที่พบบ่อยที่จะคิดว่าแนวคิดใหม่ในวัฒนธรรมและสังคมมีอยู่มาตลอดเวลา",
  str_homestory_chat_33021008 = "ไม่ใช่แค่นวนิยายเท่านั้น แต่แนวคิดเช่นวัยเด็ก ความรัก การใช้เหตุผล และอื่น ๆ ก็เป็นผลิตภัณฑ์ของยุคสมัยใหม่เช่นกัน",
  str_homestory_chat_33021009 = "เมื่อคุณชินกับมันแล้ว จะยากที่จะจินตนาการชีวิตแบบอื่น...",
  str_homestory_chat_33021010 = "ดังนั้นความเข้าใจผิดว่า \"พวกเขามีอยู่ตลอดไป\"",
  str_homestory_chat_33021011 = "มันยากที่จะเชื่อบ้าง",
  str_homestory_chat_33021012 = "ออโรเรียนไม่มีเรื่องราวให้อ่านในอดีตหรือเปล่า?",
  str_homestory_chat_33021013 = "ในอดีต เรามีมหากาพย์ ละคร และนิทาน ซึ่งมีองค์ประกอบของการเล่าเรื่อง แต่ก็แตกต่างจากนวนิยายอย่างมาก",
  str_homestory_chat_33021014 = "ล่าสุด ฉันได้อ่านนิยายที่ขายดีบางเล่มที่แสดงอยู่ในร้านหนังสือ ถ้าเทียบกับเรื่องราวยิ่งใหญ่และอื่น ๆ...",
  str_homestory_chat_33021015 = "โครงเรื่องของพวกเขาซับซ้อนขึ้น ความรู้สึกมีความละเอียดอ่อนมากขึ้น ไม่มีข้อสงสัยว่าเป็นผลสืบเนื่องจากความเจริญรุ่งเรืองของสังคม",
  str_homestory_chat_33021016 = "หนึ่งร้อยปีที่แล้ว ชาวออโรเรียนไม่มีเวลาที่จะคิดค้นเรื่อง \"ไร้ประโยชน์\" นี้",
  str_homestory_chat_33021017 = "ฉันเห็น... การคุยกับคุณจริงๆ แน่นอนเป็นการสร้างแสงสว่าง!",
  str_homestory_chat_33022001 = "หนังสือประวัติศาสตร์",
  str_homestory_chat_33022002 = "ค่อนข้างหายากที่จะเห็นใครที่อายุเท่าคุณสนใจประวัติศาสตร์",
  str_homestory_chat_33022003 = "อ่านประวัติศาสตร์เป็นสิ่งดี แต่ต้องระมัดระวังว่าไม่ควรคิดว่าทุกสิ่งที่เขียนในหนังสือเป็นความจริงอย่างสิ้นเชิง",
  str_homestory_chat_33022004 = "ฉันเข้าใจแล้ว นายวิลเฮล์ม คุณหมายถึง \"ประวัติศาสตร์เขียนโดยผู้ชนะ\" ใช่ไหม?",
  str_homestory_chat_33022005 = "คำพูดนั้นเพียงแค่สะท้อนถึงการบิดเบือนประวัติศาสตร์อย่างตั้งใจของผู้มีอำนาจ ความเป็นจริงนั้นซับซ้อนมากกว่านั้น",
  str_homestory_chat_33022006 = "แม้ว่านักประวัติศาสตร์จะเขียนประวัติศาสตร์ด้วยเจตนาที่สูงส่งในการ \"เรียกคืนความจริง\"...",
  str_homestory_chat_33022007 = "พวกเขาถูกส่งผ่านจากจิตวิญญาณและจริยธรรมของยุคเวลาของตนเองอย่างเต็มที่",
  str_homestory_chat_33022008 = "สิ่งที่พวกเขาเขียนลงไปนั้นเป็น \"ประวัติศาสตร์ที่มองเห็นโดยคนในยุคนั้น\" ไม่ใช่ \"ประวัติศาสตร์\" มันเอง",
  str_homestory_chat_33022009 = "คุณกำลังพูดว่า... ประวัติศาสตร์ไม่สามารถกู้คืนได้อย่างถูกต้องหรือ?",
  str_homestory_chat_33022010 = "ตามที่คาดหวังจากคนรุ่นใหม่ที่อ่านประวัติศาสตร์ คุณได้สังเกตความแย้งแยะของ \"ประวัติศาสตร์และความจริง\" แล้ว",
  str_homestory_chat_33023001 = "บทกลอน.",
  str_homestory_chat_33023002 = "ฮืม, บางครั้งฉันคิดว่านายมีจิตวิญญาณที่แก่เกินอายุ แต่ก็มีครั้งที่นายทำให้ฉันประหลาดใจด้วยความสนใจที่เยาว์ช youthful",
  str_homestory_chat_33023003 = "มีคำพูดว่า \"การตายในวัยหนุ่มสาวที่ยังคงอยู่เป็นพรจากนักกวี\" คุณคิดยังไงเกี่ยวกับสิ่งนี้?",
  str_homestory_chat_33023004 = "จริงด้วยสินะ",
  str_homestory_chat_33023005 = "ความคิดของคุณนั้นอันตราย",
  str_homestory_chat_33023006 = "การเขียนกวีนิพนธ์ต้องการความกระตือรือร้นของวัยหนุ่ม ดีกว่าตายเร็ว ๆ แทนที่จะรอให้ความหลงใหลนั้นสลายไป",
  str_homestory_chat_33023007 = "ชีวิตที่ไม่มีความหลงใหลไม่คุ้มค่าที่จะใช้ชีวิตอยู่—นั่นเป็นสิ่งที่คุณคิดหรือเปล่า?",
  str_homestory_chat_33023008 = "ไม่ใช่เลยครับ แต่เรื่องนักกวีล่ะครับ?",
  str_homestory_chat_33023009 = "มีคนเชื่ออยู่เสมอว่ามีสิ่งบางอย่างเป็นจุดประสงค์ของชีวิตทั้งชีวิตของพวกเขา ใช่ไหม?",
  str_homestory_chat_33023010 = "จุดมุ่งหมายของชีวิตทั้งชีวิต... สำหรับฉัน อาจจะเป็นเส้นทางในการเข้าใกล้พระเจ้ามากขึ้น",
  str_homestory_chat_33023011 = "คุณมีสายตาที่เฉียบแหลมมาก PlayerName.",
  str_homestory_chat_33023012 = "ฉันไม่เห็นด้วย.",
  str_homestory_chat_33023013 = "คุณไม่เห็นด้วยกับ \"ทฤษฎีความสามารถภูมิธรรม\" หรือไม่?",
  str_homestory_chat_33023014 = "หมายความว่าไง",
  str_homestory_chat_33023015 = "จากทุกภาคภูมิของวรรณกรรม บทกวีคือภาคภูมิที่ต้องการความสามารถมากที่สุด",
  str_homestory_chat_33023016 = "หลายกวีที่ยิ่งใหญ่เริ่มมีชื่อเสียงในวัยหนุ่มสาว ใช้พรสวรรค์ของตนจนหมด แล้วก็กลายเป็นคนธรรมดาที่ไม่มีอะไรเด่น",
  str_homestory_chat_33023017 = "แต่คุณไม่เห็นด้วยกับชะตากรรมแบบนี้",
  str_homestory_chat_33023018 = "ตราบใดที่ยังมีชีวิต คนก็สามารถไล่ตามบทกวีที่ได้รับจากพระเจ้าด้วยวิญญาณที่ได้รับการบำเพ็ญเกิดจากประสบการณ์ในโลกนี้",
  str_homestory_chat_33023019 = "นายคิดอย่างนั้นเหรอ",
  str_homestory_chat_33023020 = "ฉัน... อาจจะเป็นไปได้ ฉันไม่ชอบความคิดที่จะผูกมัดความเป็นไปได้ทั้งหมดของชีวิตเพียงแค่ \"เยาว์วัย\"",
  str_homestory_chat_33023021 = "แต่คิด ๆ ไป นั่นแหละที่คุณหมายถึงใช่ไหม",
  str_homestory_chat_33023022 = "แต่ฉันไม่สามารถแสดงออกได้ดีเท่าคุณ! คุณน่าทึ่งมาก คุณวิลเฮล์ม!",
  str_homestory_chat_33024001 = "หนังสือวิทยาศาสตร์ที่นิยม",
  str_homestory_chat_33024002 = "วิทยาศาสตร์, หรือ... ไม่มีข้อสงสัยว่ามันได้สร้างสรรค์สิ่งที่ดีให้กับสังคมอย่างมาก",
  str_homestory_chat_33024003 = "แต่ด้วยกรอบวิทยาศาสตร์ในปัจจุบัน ชาวออโรเรียนแน่นอนกำลังห่างหายจากความจริง",
  str_homestory_chat_33024004 = "เอ่อ, ยังไงเหรอ?",
  str_homestory_chat_33024005 = "วิกตอเรียเคยบอกคุณว่า \"ความจริงมีหลายมิติ\" หรือไม่ครับ?",
  str_homestory_chat_33024006 = "เธอพูดแบบนั้นบ่อยนะ!",
  str_homestory_chat_33024007 = "นี่คือที่ที่ความลึกลับอยู่",
  str_homestory_chat_33024008 = "วิทยาศาสตร์สร้างขึ้นบนความสามารถในการคาดคะเน",
  str_homestory_chat_33024009 = "การทำสิ่งใดสิ่งหนึ่งถึงหมื่นครั้งและได้ผลลัพธ์เดียวกันทุกครั้งนั่นคือสิ่งที่ทำให้มันกลายเป็น \"ข้อสรุปทางวิทยาศาสตร์\"",
  str_homestory_chat_33024010 = "แต่สัจธรรมนั้นอยู่ในประกายที่หนึ่งในล้าน",
  str_homestory_chat_33024011 = "คุณจับตามองได้ในครั้งเดียว และสายตานั้น ไม่ว่าคุณจะมองกี่ครั้ง ก็มักจะแตกต่างกันเสมอ",
  str_homestory_chat_33024012 = "เข้าใจหรือยัง?",
  str_homestory_chat_33024013 = "เข้าใจ",
  str_homestory_chat_33024014 = "ไร้สาระ ถ้าคุณจริงๆ นั้นสามารถเข้าใจได้จากคำพูดที่ฉันวางวาย แล้วเราต้องการทรู ออเดอร์ ทำไมล่ะ?",
  str_homestory_chat_33024015 = "...",
  str_homestory_chat_33024016 = "ไม่เข้าใจแฮะ",
  str_homestory_chat_33024017 = "ไม่เป็นไรนะ คุณชอบวิทยาศาสตร์ ดังนั้นก็ควรศึกษามันต่อไป",
  str_homestory_chat_33024018 = "เมื่อวิทยาศาสตร์ไปถึงจุดสูงสุดของมัน มันอาจกลายเป็นทางเข้าอีกหนึ่งไปสู่ความจริง",
  str_homestory_chat_33025001 = "ข้อความทางธรรมะ",
  str_homestory_chat_33025002 = "???",
  str_homestory_chat_33025003 = "...โอ๊ะ, งั้นเหรอ.",
  str_homestory_chat_33025004 = "คุณอ่าน... มันเรียกว่าอะไรนะ? \"นิยายแฟนตาซี\"? อันที่ตั้งอยู่บนตำนาน.",
  str_homestory_chat_33025005 = "และนั่นเป็นเหตุผลว่าทำไมคุณถึงถูกดึงดูดโดยแนวคิดและการตั้งค่าในเรื่องนั้น ใช่ไหม?",
  str_homestory_chat_33025006 = "ฮะ? ไม่ คุณวิลเฮล์ม.",
  str_homestory_chat_33025007 = "ฟังคุณพูดถึง \"ความจริง\" และ \"ท่านลอร์ด\" บ่อยๆ ฉันต้องการที่จะเข้าใจว่าคุณกำลังพูดถึงอะไร",
  str_homestory_chat_33025008 = "?!",
  str_homestory_chat_33025009 = "สำหรับ...ฉันเหรอ?",
  str_homestory_chat_33025010 = "ใช่ ฉันพบว่าการคุยของคุณน่าสนใจและอยากจะสามารถตอบกลับคุณบางครั้ง",
  str_homestory_chat_33025011 = "...อืม, มันจะผิดไปไหมถ้าอ่านข้อความทางศาสนาด้วยความคิดที่ไม่จริงจังเช่นนี้?",
  str_homestory_chat_33025012 = "...ไม่ มันไม่ใช่.",
  str_homestory_chat_33025013 = "เป็นอะไรไปล่ะ",
  str_homestory_chat_33025014 = "ไม่มีอะไร! ไปอ่านเลยตอนนี้",
  str_homestory_chat_33025015 = "ถ้ามีอะไรที่คุณไม่เข้าใจ... อย่าลังเลที่จะถามฉันนะ",
  str_homestory_chat_33199999 = "ฝันอะไรน่าสนใจบ้างในช่วงนี้รึเปล่า?",
  str_homestory_chat_33121001 = "ฝันที่น่าสนใจ?",
  str_homestory_chat_33121002 = "นึกไม่ออกเลยสักอย่างเดียว...",
  str_homestory_chat_33121003 = "ฮืม... คุณอยู่ภายใต้ความกดดันอย่างมากหรือเปล่า?",
  str_homestory_chat_33121004 = "ไม่เหนื่อยเหรอที่ต้องนอนโดยไม่มีฝันดี?",
  str_homestory_chat_33121005 = "ฮะ? ฉันไม่คิดว่าจะพูดอย่างนั้น...",
  str_homestory_chat_33121006 = "ความเครียดมากมายหายไปหลังจากนอนหลับดีในคืนนั้น",
  str_homestory_chat_33121007 = "งั้นรึ? แต่...",
  str_homestory_chat_33121008 = "ได้สิ",
  str_homestory_chat_33121009 = "อ๊ะ PlayerName คุณเป็นผู้ชายที่มองโลกในแง่ดีนะ!",
  str_homestory_chat_33121010 = "ฮะ? ความฝันของฉันนำคุณมาสู่ข้อสรุปนี้เหรอ?",
  str_homestory_chat_33121011 = "ใช่! ผู้ที่มีชีวิตที่มีความสุขและปฏิบัติต่อผู้อื่นด้วยการมองโลกในแง่ดี...",
  str_homestory_chat_33121012 = "พวกเขาจะมีสิ่งสวยงามมากมายกับคนที่รักในความฝันของพวกเขา!",
  str_homestory_chat_33121013 = "หึหึ แต่ว่ามีวิธีที่ง่ายกว่านี้อีกนะ",
  str_homestory_chat_33121014 = "มาหาฉันเมื่อไหร่ก็ได้ถ้าคุณอยากฝันดีนะ!",
  str_homestory_chat_33121015 = "ได้เลย!",
  str_homestory_chat_33122001 = "โลกที่ไม่มีอิคลิพไซท์",
  str_homestory_chat_33122002 = "ว้าว ขอเวลานั่งคิดแป๊บนึงนะครับ...",
  str_homestory_chat_33122003 = "นั่นคงเป็นฟองสบู่ที่ไม่มีจุดด่างเลย!",
  str_homestory_chat_33122004 = "ฟองสบู่ที่สวยที่สุด สมบูรณ์ที่สุด!",
  str_homestory_chat_33122005 = "คุณทำอะไรที่นั่น?",
  str_homestory_chat_33122006 = "ฉันเดินทางรอบๆ ด้วยทุกคน",
  str_homestory_chat_33122007 = "ว้าว ฉันหวังว่าฉันจะอยู่ที่นั่นกับคุณ!",
  str_homestory_chat_33122008 = "เรากอดลมและมองดูการกำเนิดโลกใหม่ด้วยกันบนยอดโคลอสซัส...",
  str_homestory_chat_33122009 = "เราทำงานร่วมกันเพื่อฟื้นฟูบ้านเกิดของเรา",
  str_homestory_chat_33122010 = "คุณนี่ใจดีและเสียสละตัวเองแม้ในฝันของคุณ!",
  str_homestory_chat_33122011 = "มันเป็นสิ่งสำคัญมากที่จะคืนสีสันให้กับฟองอากาศจริง ๆ",
  str_homestory_chat_33122012 = "คุณจะพาฉันไปด้วยกันคราวหน้าเพื่อสัมผัสฝันที่สวยงามนี้ด้วยกันไหม?",
  str_homestory_chat_33122013 = "แน่นอน แต่ฉันไม่รู้ว่าจะเมื่อไหร่...",
  str_homestory_chat_33123001 = "หลงโจว.",
  str_homestory_chat_33123002 = "หลงโจว ฉันอ่านเกี่ยวกับมันในหนังสือเทพนิยาย...",
  str_homestory_chat_33123003 = "เทพนิยายที่นั่นค่อนข้างลึกซึ้งนะ",
  str_homestory_chat_33123004 = "พวกเขาชอบใช้คำศัพท์ยาว ๆ และวลีที่แปลกประหลาด ทำให้ฉันเข้าใจยาก...",
  str_homestory_chat_33123005 = "วัฒนธรรมของหลงโจวนั้นลึกซึ้งและกว้างขวางจริงๆ",
  str_homestory_chat_33123006 = "อุปกรณ์ของพวกเขา, ปฏิทิน, และออโรเรียนนั้นสร้างความสนใจอย่างแท้จริง",
  str_homestory_chat_33123007 = "จริงเหรอ? ฉันไม่เคยเห็นออโรเรียนจากหลงโจวมาก่อนเลย",
  str_homestory_chat_33123008 = "ฉันจะขอให้บรรพบุรุษของฉันมาปรากฏตัวในฝันของฉันคืนนี้",
  str_homestory_chat_33123009 = "พูดเป็นเล่นน่า?",
  str_homestory_chat_33123010 = "ถ้าฉันแนะนำออโรเรียนบางคนให้คุณรู้จักในครั้งหน้าล่ะ?",
  str_homestory_chat_33123011 = "วู้ว! คุณน่ารักกับฉันมากเหมือนกับบรรพบุรุษของฉันเลย!",
  str_homestory_chat_33124001 = "การแสดงละครสัตว์",
  str_homestory_chat_33124002 = "หืม... การแสดง?",
  str_homestory_chat_33124003 = "ฉันดูมาเยอะเมื่อฉันอยู่ในคณะละครสัตว์...",
  str_homestory_chat_33124004 = "แม้ว่าฉันจะจำไม่ค่อยได้...",
  str_homestory_chat_33124005 = "ฉันรู้แน่ ๆ ว่าพวกเขาเป็นนักแสดงที่น่าทึ่ง!",
  str_homestory_chat_33124006 = "ส่วนไหนของการแสดงที่เป็นที่ชอบของคุณ?",
  str_homestory_chat_33124007 = "ฉันเดาว่าการโยนมีด?",
  str_homestory_chat_33124008 = "การโยนมีดเหรอ? ไม่รู้ว่าคุณชอบความตื่นเต้นแบบนี้นี่นา",
  str_homestory_chat_33124009 = "มันตื่นเต้นและมักจะจบด้วยดีเสมอ!",
  str_homestory_chat_33124010 = "นั่นเป็นเหตุผลที่ฉันก็เป็นแฟน",
  str_homestory_chat_33124011 = "ฉันเดาว่านี่คือการแสดงมายากลเหรอ?",
  str_homestory_chat_33124012 = "การแสดงมายากล? เจโน่เป็นนักมายากลที่ยอดเยี่ยม!",
  str_homestory_chat_33124013 = "ฉันยังจำความลึกลับที่รู้สึกได้! เขาสามารถบอกได้มากมายเพียงด้วยการวาดไพ่เพียงไม่กี่ใบ!",
  str_homestory_chat_33124014 = "ฮูม... ฉันคิดถึงทุกคนจากคณะละครสัตว์...",
  str_homestory_chat_33124015 = "ถ้าเรามีโอกาส มาดูการแสดงคณะละครสัตว์ด้วยกันนะ!",
  str_homestory_chat_33124016 = "ดีล!",
  str_homestory_chat_33125001 = "อีราเวล.",
  str_homestory_chat_33125002 = "อีราเวล... นั่นเป็นบ้านเกิดของคุณใช่ไหม?",
  str_homestory_chat_33125003 = "ฉันเกิดขึ้นบนเรือ ความรู้สึกที่เรียกว่า \"บ้าน\" สำหรับฉันแปลกประหลาด",
  str_homestory_chat_33125004 = "คุณชอบอีราเวลหรือไม่?",
  str_homestory_chat_33125005 = "ใช่ครับ ชาวเราอาศัยอยู่ที่นั่นมาหลายชั่วอายุคนนับแต่เดิมนั้นแหละ",
  str_homestory_chat_33125006 = "แต่ฉันใช้เวลาสิบเจ็ดปีใต้ดิน",
  str_homestory_chat_33125007 = "ยังมีอีกหลายอย่างที่ฉันไม่รู้เกี่ยวกับบรรพบุรุษของฉัน",
  str_homestory_chat_33125008 = "นั่นเป็นหนึ่งในเหตุผลที่ฉันเดินทาง",
  str_homestory_chat_33125009 = "ว้าว. เคเลสไทต์ก็กำลังพยายามเรียนรู้เกี่ยวกับบรรพบุรุษของเขาเหรอ?",
  str_homestory_chat_33125010 = "เราค่อนข้างคล้ายกันนะ, ใช่ไหม?",
  str_homestory_chat_33125011 = "บางทีบรรพบุรุษของฉันอาจจะรู้จักบรรพบุรุษของคุณเหรอ?",
  str_homestory_chat_33125012 = "อาจจะเคยเป็นเพื่อนที่ดีกันในอดีต!",
  str_homestory_chat_33125013 = "ฮ่าๆ นั่นเป็นความคิดที่น่าสนใจจริงๆนะ",
  str_homestory_chat_33125014 = "ฮิฮิ บรรพบุรุษของเราต้องมีความสุขมากที่ได้เห็นเราดำเนินต่อมิตรภาพของพวกเขา!",
  str_homestory_chat_33299999 = "คุณมีสิ่งที่ต้องการปกป้องรึเปล่า?",
  str_homestory_chat_33221001 = "สิ่งที่ฉันต้องการปกป้อง...",
  str_homestory_chat_33221002 = "มันเยอะมากเลยนะ คุณรู้มั้ย?",
  str_homestory_chat_33221003 = "คุณเจาะจงอีกนิดได้ไหม?",
  str_homestory_chat_33221004 = "อืมม... มันยากที่จะอธิบาย",
  str_homestory_chat_33221005 = "คุณถามเรื่องอะไรอยู่เหรอ?",
  str_homestory_chat_33221006 = "จากแนวคิดที่ยิ่งใหญ่เช่น อุดมการณ์และความเชื่อ.",
  str_homestory_chat_33221007 = "ลงมาถึงรายละเอียดเล็ก ๆ ที่ซับซ้อน",
  str_homestory_chat_33221008 = "บางทีคุณอาจจะให้ตัวอย่างให้ฉันได้บ้าง",
  str_homestory_chat_33221009 = "อย่าง...",
